	// bleibt das PHASE-04-Verhalten unveraendert.
	onOpenInspector?: (key: string) => void;
	// PHASE-06: Fenster, nach dem ein abgeschlossener/fehlgeschlagener/
	// gestoppter Top-Level-Eintrag automatisch aus dem Dock verschwindet.
	completedEntryVisibleMs?: number;
	// PHASE-06: wird nach der zweiten "s"-Bestaetigung mit dem Key des
	// betroffenen Eintrags aufgerufen. Der Controller selbst liefert keinen
	// Stop-Kanal (bleibt reine Zustandsmaschine) - die Wiring-Schicht
	// entscheidet, wie tatsaechlich gestoppt wird (siehe fleet-stop.ts).
	onStop?: (key: string) => void;
}

export class FleetDockController {
	private selectedKey: string | undefined;
	private lastIndex = 0;
	private expandedKey: string | undefined;
	private active = false;
	private activationEditorLength = 0;
	private cachedEntries: FleetAgentEntry[] = [];
	private cachedAt = Number.NEGATIVE_INFINITY;
	private readonly dismissedKeys = new Set<string>();
	private stopArmedKey: string | undefined;
	private readonly state: SubagentState;
	private readonly options: FleetDockControllerOptions;

	// Keine TS-Parameter-Properties hier: --experimental-strip-types (test:unit)
	// kann diese Syntax nicht strippen, nur --experimental-transform-types kann das.
	constructor(state: SubagentState, options: FleetDockControllerOptions = {}) {
		this.state = state;
		this.options = options;
	}

	private now(): number {
		return this.options.now?.() ?? Date.now();
	}

	private refreshIntervalMs(): number {
		return this.options.refreshIntervalMs ?? DEFAULT_REFRESH_INTERVAL_MS;
	}

	private maxRows(): number {
		return this.options.maxRows ?? MAX_DOCK_ROWS;
	}

	private completedEntryVisibleMs(): number {
		return this.options.completedEntryVisibleMs ?? DEFAULT_COMPLETED_ENTRY_VISIBLE_MS;
	}

	/**
	 * Entfernt dismisste Eintraege sowie automatisch verfallene Top-Level-
	 * Eintraege (terminal, aelter als completedEntryVisibleMs()). Kaskadiert
	 * auf Kind-Eintraege ueber parentKey, da buildFleetEntries() Eltern immer
	 * vor ihren Kindern liefert (siehe fleet-projection.ts).
	 */
	private filterVisible(entries: FleetAgentEntry[], now: number): FleetAgentEntry[] {
		const removedKeys = new Set<string>();
		const visible: FleetAgentEntry[] = [];
		for (const entry of entries) {
			const parentRemoved = entry.parentKey !== undefined && removedKeys.has(entry.parentKey);
			const expired = entry.depth === 0 && isTerminalState(entry.state) && now - entry.updatedAt >= this.completedEntryVisibleMs();
			if (parentRemoved || this.dismissedKeys.has(entry.key) || expired) {
				removedKeys.add(entry.key);
				continue;
			}
			visible.push(entry);
		}
		return visible;
	}

	/** Liefert die aktuelle FleetAgentEntry-Liste, throttled auf refreshIntervalMs(). */
	getEntries(): FleetAgentEntry[] {
		const now = this.now();
		if (now - this.cachedAt < this.refreshIntervalMs()) return this.cachedEntries;
		const raw = buildFleetEntries(this.state, { now: () => now, ...this.options.deps });
		this.cachedEntries = this.filterVisible(raw, now);
		this.cachedAt = now;
		this.resolveSelection();
		return this.cachedEntries;
	}

	/** Erzwingt eine Neuberechnung beim naechsten getEntries()-Aufruf. */
	invalidateCache(): void {
		this.cachedAt = Number.NEGATIVE_INFINITY;
	}

	private resolveSelection(): void {
		const entries = this.cachedEntries;
		if (this.stopArmedKey !== undefined && !entries.some((entry) => entry.key === this.stopArmedKey)) {
			// Der bewaffnete Eintrag ist verschwunden (gestoppt+abgelaufen, dismisst,
			// oder ausserhalb des Sichtbarkeitsfensters) - eine stehende Bestaetigung
			// darf nicht auf einen spaeter wiederverwendeten Key uebertragen werden.
			this.stopArmedKey = undefined;
		}
		if (entries.length === 0) {
			this.selectedKey = undefined;
			this.expandedKey = undefined;
			this.lastIndex = 0;
			return;
		}
		if (this.selectedKey !== undefined) {
			const idx = entries.findIndex((entry) => entry.key === this.selectedKey);
			if (idx !== -1) {
				this.lastIndex = idx;
				return;
			}
		}
		const clamped = Math.min(this.lastIndex, entries.length - 1);
		this.selectedKey = entries[clamped]!.key;
		this.lastIndex = clamped;
		if (this.expandedKey !== undefined && !entries.some((entry) => entry.key === this.expandedKey)) {
			this.expandedKey = undefined;
		}
	}

	getSelectedKey(): string | undefined {
		return this.selectedKey;
	}

	getExpandedKey(): string | undefined {
		return this.expandedKey;
	}

	isActive(): boolean {
		return this.active;
	}

	moveSelection(direction: 1 | -1): void {
		const entries = this.getEntries();
		if (entries.length === 0) return;
		const currentIdx = this.selectedKey !== undefined ? entries.findIndex((entry) => entry.key === this.selectedKey) : -1;
		const base = currentIdx === -1 ? 0 : currentIdx;
		const nextIdx = Math.max(0, Math.min(entries.length - 1, base + direction));
		this.selectedKey = entries[nextIdx]!.key;
		this.lastIndex = nextIdx;
	}

	toggleExpanded(): void {
		if (this.selectedKey === undefined) return;
		this.expandedKey = this.expandedKey === this.selectedKey ? undefined : this.selectedKey;
	}

	/** true, solange fuer key eine Stop-Bestaetigung aussteht ("s" wurde einmal gedrueckt). */
	isStopArmed(key: string): boolean {
		return this.stopArmedKey === key;
	}

	/**
	 * Blendet einen bereits terminalen (completed/error/stopped) Top-Level-
	 * Eintrag lokal aus. Laufende/pausierte Eintraege und Kind-Zeilen koennen
	 * nicht direkt dismisst werden (Aenderungsregel: nur "erledigte
	 * Eintraege"). Wirkt sofort, nicht erst nach dem naechsten throttled
	 * getEntries()-Aufruf.
	 */
	dismiss(key: string | undefined = this.selectedKey): boolean {
		if (key === undefined) return false;
		const entry = this.cachedEntries.find((candidate) => candidate.key === key);
		if (!entry || entry.depth !== 0 || !isTerminalState(entry.state)) return false;
		this.dismissedKeys.add(key);
		this.invalidateCache();
		this.getEntries();
		return true;
	}

	activate(): void {
		const entries = this.getEntries();
		this.active = true;
		if (this.selectedKey === undefined && entries.length > 0) {
			this.selectedKey = entries[0]!.key;
			this.lastIndex = 0;
		}
	}

	deactivate(): void {
		this.active = false;
		this.stopArmedKey = undefined;
	}

	/**
	 * Terminal-Input-Handler fuer ctx.ui.onTerminalInput(). ctx ist absichtlich
	 * auf getEditorText() minimiert statt des vollen ExtensionUIContext, um die
	 * Kopplung an den echten Editor-Zustand testbar zu halten.
	 */
	handleTerminalInput(ctx: { getEditorText(): string }, data: string): TerminalInputResult {
		if (isKeyRelease(data)) return undefined;
		// Compares against the length captured at activation time, not against 0:
		// "super+down" (below) can activate the dock while the editor already has
		// text, and that starting text must not immediately self-heal the very
		// next keystroke just because it is still non-empty.
		if (this.active && ctx.getEditorText().length !== this.activationEditorLength) {
			this.deactivate();
		}
		if (!this.active) {
			// PHASE-09: super+down is a deliberate, always-available jump to the
			// dock, independent of editor content - unlike plain "down", which
			// only activates when the editor is already empty (see class header).
			if (matchesKey(data, "super+down") || (ctx.getEditorText().length === 0 && matchesKey(data, "down"))) {
				this.activationEditorLength = ctx.getEditorText().length;
				this.activate();
				return { consume: true };
			}
			return undefined;
		}
		if (this.stopArmedKey !== undefined) {
			if (matchesKey(data, "s") && this.stopArmedKey === this.selectedKey) {
				const key = this.stopArmedKey;
				this.stopArmedKey = undefined;
				this.options.onStop?.(key);
				return { consume: true };
			}
			// Jede andere Taste entwaffnet still statt ihre eigentliche Wirkung zu
			// entfalten UND das Stoppen auszuloesen - verhindert ein versehentliches
			// Stoppen durch eine spaeter zufaellig erneut gedrueckte "s"-Taste nach
			// einer Aktion, die den Fokus/die Selektion veraendert hat.
			this.stopArmedKey = undefined;
			if (matchesKey(data, "escape")) return { consume: true };
		}
		if (matchesKey(data, "escape")) {
			this.deactivate();
			return { consume: true };
		}
		if (matchesKey(data, "up")) {
			this.moveSelection(-1);
			return { consume: true };
		}
		if (matchesKey(data, "down")) {
			this.moveSelection(1);
			return { consume: true };
		}
		if (matchesKey(data, "return")) {
			if (this.options.onOpenInspector && this.selectedKey !== undefined) {
				this.options.onOpenInspector(this.selectedKey);
			} else {
				this.toggleExpanded();
			}
			return { consume: true };
		}
		if (matchesKey(data, "s")) {
			const key = this.selectedKey;
			const entry = key !== undefined ? this.cachedEntries.find((candidate) => candidate.key === key) : undefined;
			if (!entry || entry.source !== "async" || !entry.canStop || !entry.asyncDir) return undefined;
			this.stopArmedKey = entry.key;
			return { consume: true };
		}
		if (matchesKey(data, "d")) {
			return this.dismiss() ? { consume: true } : undefined;
		}
		return undefined;
	}

	/** Component fuer setWidget's Factory-Overload. Kein eigener Render-Cache noetig, da getEntries() bereits throttled. */
	createComponent(theme: Theme): Component {
		return {
			render: (width: number): string[] => {
				const entries = this.getEntries();
				return renderFleetDock(entries, this.selectedKey, {
					width,
					theme,
					expandedKey: this.expandedKey,
					maxRows: this.maxRows(),
					now: this.now(),
					stopArmedKey: this.stopArmedKey,
					// PHASE-08: nur mit Tastaturfokus wird die Tastenkuerzelzeile
					// gerendert (siehe fleet-dock.ts).
					active: this.active,
				});
			},
			invalidate: () => {},
		};
	}
}

export function createFleetDockController(state: SubagentState, options?: FleetDockControllerOptions): FleetDockController {
	return new FleetDockController(state, options);
}

/**
 * Fleet Status Dock Wiring (PHASE-04, erweitert um den Inspector in PHASE-05).
 *
 * Verdraht FleetDockController UND FleetInspectorController mit der
 * Pi-Extension-API: Widget-Registrierung (setWidget mit aboveEditor/
 * belowEditor-Placement, je ein Widget-Key pro Controller), ein einziger
 * gemeinsamer Terminal-Input-Handler (ctx.ui.onTerminalInput) und die
 * Deaktivierung des alten Async-Widgets bei aktiver FleetView oder explizit
 * deaktiviertem ui.asyncWidget.
 *
 * Wird von src/extension/index.ts ueber genau 3 additive Call-Sites
 * angebunden (in resetSessionState, im tool_result-Handler, in
 * runtimeCleanup) - keine bestehende Zeile dort wird veraendert. PHASE-05
 * fuegt in index.ts KEINE einzige neue Zeile hinzu: der Inspector wird
 * vollstaendig in diese bestehende Fabrik integriert, ihr Rueckgabetyp
 * (FleetDockWiring) bleibt unveraendert - dieselben drei Hook-Callbacks
 * uebernehmen die Inspector-Lifecycle-Pflege mit.
 *
 * Mutual-Exclusion-Design (Gesamtabschlusskriterium 8), zweischichtig:
 *
 * 1. state.suppressAsyncWidget (types.ts) wird hier synchron beim Aufbau
 *    gesetzt und von async-job-tracker.ts's rerenderWidget() bei JEDEM
 *    Aufruf live geprueft (Poller-Tick, handleStarted/handleComplete,
 *    Statusaenderungen laufender Jobs). Das deckt alle Stellen ab, an denen
 *    das alte Widget unabhaengig von einem tool_result-Event erneut gerendert
 *    werden kann - ohne dass async-job-tracker.ts's showAsyncWidget-Option
 *    (aus index.ts's unveraendertem Konstruktionsaufruf) angefasst wird.
 * 2. onToolResult() ueberschreibt zusaetzlich WIDGET_KEY aktiv mit
 *    setWidget(WIDGET_KEY, undefined), da index.ts's tool_result-Handler
 *    selbst einen direkten renderWidget()-Aufruf enthaelt (Zeile ~595, nicht
 *    ueber async-job-tracker.ts geroutet) - dessen unveraenderte Bedingung
 *    bleibt byte-identisch, ein reiner Zusatzaufruf danach genuegt.
 *
 * Ohne Schicht 1 kehrt das alte Widget bei jeder Job-Statusaenderung
 * zwischen zwei tool_result-Events zurueck (empirisch beim zweiten
 * Verifikationsdurchlauf gefunden, siehe DECISIONS.md DEC-026). Das deckt
 * gleichzeitig den PHASE-05-Punkt "Widget waehrend geoeffnetem Inspector
 * ausblenden" ab: suppressAsyncWidget gilt fuer die gesamte Lebensdauer bei
 * aktiver FleetView, unabhaengig vom Inspector-Offen-Zustand - keine
 * zusaetzliche Bedingung noetig (siehe DECISIONS.md).
 *
 * ui.asyncWidget-Praezedenz (siehe DECISIONS.md DEC-024/DEC-025): nur die
 * "verstecken"-Richtung ist umgesetzt (asyncWidget:false versteckt das alte
 * Widget zuverlaessig, auch wenn showAsyncWidget/fleetView das nicht
 * verlangen wuerden). Die umgekehrte Richtung (asyncWidget:true soll das
 * Widget erzwingen, obwohl config.ui.showAsyncWidget===false den
 * renderWidget()-Aufruf in index.ts bereits komplett uebersprungen hat)
 * ist bewusst NICHT umgesetzt: dafuer muesste diese Datei renderWidget()
 * und state.asyncJobs selbst duplizieren, ohne einen realen Anwendungsfall
 * in der dokumentierten Rueckfallkonfiguration (README.md) zu bedienen -
 * dort wird asyncWidget:true nur zusammen mit fleetView:false verwendet,
 * wo showAsyncWidget ohnehin unangetastet (default true) bleibt.
 *
 * Input-Routing (PHASE-05, Zwei-Ebenen-Escape): der eine gemeinsame
 * onTerminalInput-Handler prueft zuerst, ob der Inspector offen ist - wenn
 * ja, geht JEDE Eingabe exklusiv an ihn (er konsumiert Scroll/Space/Escape
 * vollstaendig, Escape schliesst dabei NUR ihn). Erst wenn er geschlossen
 * ist, faellt die Eingabe wie bisher an FleetDockController - dessen eigenes
 * Escape wird dadurch automatisch zur zweiten Eskalationsstufe (Dock
 * deaktivieren), ohne dass beide Controller je gleichzeitig auf dieselbe
 * Taste reagieren. Enter oeffnet den Inspector ueber FleetDockController-
 * Options onOpenInspector (siehe fleet-dock-controller.ts), nicht hier.
 */

import type { ExtensionContext } from "@earendil-works/pi-coding-agent";
import { FLEET_DOCK_WIDGET_KEY, FLEET_INSPECTOR_WIDGET_KEY, WIDGET_KEY, type ExtensionConfig, type SubagentState } from "../../shared/types.ts";
import { createFleetDockController, type FleetDockController } from "./fleet-dock-controller.ts";
import { createFleetInspectorController, type FleetInspectorController } from "./fleet-inspector-controller.ts";
import { resolveInspectorTrustedRoots } from "../shared/fleet-transcript-reader.ts";
import { requestFleetStop } from "./fleet-stop.ts";
import type { FleetAgentEntry } from "../shared/fleet-projection.ts";

function isStaleExtensionContextError(error: unknown): boolean {
	return error instanceof Error && error.message.includes("Extension context no longer active");
}

export interface FleetDockWiring {
	readonly fleetViewEnabled: boolean;
	onSessionStart(ctx: ExtensionContext): void;
	onToolResult(ctx: ExtensionContext): void;
	dispose(): void;
}

export function createFleetDockWiring(state: SubagentState, config: ExtensionConfig): FleetDockWiring {
	const fleetViewEnabled = config.ui?.fleetView === true;
	const asyncWidgetExplicitlyDisabled = config.ui?.asyncWidget === false;
	const overridesOldWidget = fleetViewEnabled || asyncWidgetExplicitlyDisabled;
	const placement = config.ui?.fleetViewPlacement ?? "belowEditor";

	let inspectorController: FleetInspectorController | undefined;

	// PHASE-06: gemeinsamer Stop-Dispatch fuer Dock UND Inspector - beide
	// Controller kennen nur den Key, nicht den vollen FleetAgentEntry; die
	// Wiring-Schicht loest den Key gegen die aktuelle Entry-Liste auf und ruft
	// dann requestFleetStop() (siehe fleet-stop.ts, reiner Dispatch ueber den
	// bestehenden dateibasierten Control-Kanal, keine neue Orchestrierung).
	function handleFleetStop(key: string): void {
		const entry: FleetAgentEntry | undefined = controller?.getEntries().find((candidate) => candidate.key === key);
		if (!entry) return;
		requestFleetStop(entry);
		controller?.invalidateCache();
	}

	const controller: FleetDockController | undefined = fleetViewEnabled
		? createFleetDockController(state, {
				onOpenInspector: (key) => inspectorController?.open(key),
				onStop: handleFleetStop,
			})
		: undefined;
	inspectorController = controller
		? createFleetInspectorController(() => controller.getEntries(), {
				trustedRoots: () =>
					resolveInspectorTrustedRoots({
						sessionFile: state.lastUiContext?.sessionManager.getSessionFile() ?? null,
						projectCwd: state.baseCwd,
						worktreeBaseDir: config.worktreeBaseDir,
					}),
				onStop: handleFleetStop,
			})
		: undefined;

	let unsubscribeTerminalInput: (() => void) | undefined;

	// Schicht 1 (siehe Kopfkommentar): staendig gueltig fuer die gesamte
	// Lebensdauer dieser Extension-Instanz, nicht nur nach einem tool_result.
	state.suppressAsyncWidget = overridesOldWidget;

	function routeTerminalInput(ctx: ExtensionContext, data: string): { consume?: boolean; data?: string } | undefined {
		if (inspectorController?.isOpen()) return inspectorController.handleTerminalInput(data);
		if (!controller) return undefined;
		return controller.handleTerminalInput({ getEditorText: () => ctx.ui.getEditorText() }, data);
	}

	function onSessionStart(ctx: ExtensionContext): void {
		if (!controller || !ctx.hasUI) return;
		unsubscribeTerminalInput?.();
		unsubscribeTerminalInput = ctx.ui.onTerminalInput((data) => routeTerminalInput(ctx, data));
		ctx.ui.setWidget(FLEET_DOCK_WIDGET_KEY, (_tui, theme) => controller.createComponent(theme), { placement });
		if (inspectorController) {
			ctx.ui.setWidget(FLEET_INSPECTOR_WIDGET_KEY, (_tui, theme) => inspectorController!.createComponent(theme), { placement });
		}
	}

	function onToolResult(ctx: ExtensionContext): void {
		if (!ctx.hasUI) return;
		// Schicht 2 (siehe Kopfkommentar): index.ts's eigener direkter
		// renderWidget()-Aufruf im selben Handler ist nicht ueber
		// async-job-tracker.ts geroutet und braucht daher einen Zusatzaufruf.
		if (overridesOldWidget) {
			ctx.ui.setWidget(WIDGET_KEY, undefined);
		}
		controller?.invalidateCache();
		// "ereignisnahe" Haelfte der Live-Transcript-Aktualisierung (die
		// 500ms-Throttle in FleetInspectorController ist der Poll-Fallback).
		inspectorController?.invalidateTranscriptCache();
		if (overridesOldWidget || controller) {
			ctx.ui.requestRender?.();
		}
	}

	function dispose(): void {
		unsubscribeTerminalInput?.();
		unsubscribeTerminalInput = undefined;
		if (!controller) return;
		try {
			if (state.lastUiContext?.hasUI) {
				state.lastUiContext.ui.setWidget(FLEET_DOCK_WIDGET_KEY, undefined);
				if (inspectorController) {
					state.lastUiContext.ui.setWidget(FLEET_INSPECTOR_WIDGET_KEY, undefined);
				}
			}
		} catch (error) {
			if (!isStaleExtensionContextError(error)) throw error;
		}
	}

	return { fleetViewEnabled, onSessionStart, onToolResult, dispose };
}

/**
 * Fleet-Zustandsprojektion (PHASE-03).
 *
 * Konsolidiert fuenf im Fork parallel existierende, teils inkonsistente
 * Progress-Schemas (anonymer foregroundControls-Wert, AsyncJobState /
 * AsyncRunSummary, NestedRunSummary / PublicNestedRunSummary,
 * ForegroundResumeRun, SingleResult / Details) zu einem einzigen,
 * UI-unabhaengigen Modell: FleetAgentEntry.
 *
 * State-Vokabular-Mapping (mapRawStateToFleetState), da mindestens vier
 * inkonsistente Rohvokabulare im Umlauf sind:
 *
 *   Rohwert                 | Herkunft                                 | FleetAgentState
 *   ------------------------|-------------------------------------------|------------------
 *   "queued", "pending"     | AsyncStatus/AsyncJobState/AsyncJobStep     | "running"
 *   "running"                | alle                                       | "running"
 *   "complete", "completed" | AsyncStatus/SubagentResultStatus/...       | "completed"
 *   "failed"                 | alle                                       | "error"
 *   "paused"                 | alle                                       | "paused"
 *   "stopped"                | alle                                       | "stopped"
 *   "detached"                | SubagentResultStatus/WorkflowNodeStatus    | "running" + detached:true
 *
 * Design-Entscheidung "flache Liste statt Rekursion": Live-Parallel-/
 * Chain-Kinder existieren im durablen State ohnehin nicht als Array
 * (state.foregroundControls haelt nur EIN Objekt pro Top-Level-runId, das
 * von jedem Kind-Update ueberschrieben wird). Nur Nested-Runs sind wirklich
 * rekursiv. Ein children?:FleetAgentEntry[]-Feld waere fuer Foreground-
 * Parallel/Chain dauerhaft leer, fuer Nested aber "echt" - inkonsistente
 * Semantik. Stattdessen: parentKey + depth, Consumer gruppiert selbst.
 *
 * KNOWN GAP 1: Watchdog-Eskalation ist nur fuer Async-/Nested-Quellen
 * moeglich. Weder der foregroundControls-Wert noch ForegroundResumeChild
 * fuehren ein watchdog-Feld.
 *
 * KNOWN GAP 2: Fuer aktive Foreground-Parallel-/Chain-Laeufe existiert im
 * Live-State kein Array aller Kinder (nur "wer zuletzt lief, gewinnt" im
 * einzigen foregroundControls-Eintrag). normalizeForegroundActive() liefert
 * daher bewusst nur EINE Sammelzeile pro Top-Level-Lauf.
 *
 * KNOWN GAP 3: Bekannter Fork-Bug - AsyncRunStepSummary (Projektion in
 * async-status.ts, Basis von listAsyncRuns()) fuehrt kein transcriptPath-
 * und kein watchdog-Feld. Nach einem Extension-Neustart (restoreActiveJobs
 * laeuft ueber genau diesen Pfad) fehlen beide Felder auf state.asyncJobs,
 * bis der naechste Poll-Tick sie aus dem rohen AsyncStatus.steps ueberschreibt.
 * transcriptPathMaybeStale markiert betroffene, disk-projizierte Eintraege;
 * fuer live aus state.asyncJobs gelesene Eintraege ist der fehlende Wert von
 * einer echten Neustart-Luecke nicht unterscheidbar und wird daher nicht
 * markiert. Kein Fix dieses Fork-Bugs - ausserhalb des PHASE-03-Scopes.
 *
 * KNOWN GAP 4: ForegroundResumeRun/ForegroundResumeChild fuehren kein
 * startedAt-Feld (nur updatedAt). normalizeForegroundRecent() faellt fuer
 * startedAt auf updatedAt zurueck, statt einen Wert zu erfinden.
 *
 * KNOWN GAP 5: Abgeschlossene/detachte Foreground-Runs (ForegroundResumeRun)
 * fuehren keine nestedChildren mehr - die Nested-Projektion existiert nur auf
 * lebenden foregroundControls-/AsyncJobState-Eintraegen.
 *
 * KNOWN GAP 6 (PHASE-05): model/thinking existieren strukturell nur auf
 * AsyncJobStep/AsyncRunStepSummary (Async-Steps). Weder der anonyme
 * foregroundControls-Wert noch ForegroundResumeChild/NestedStepSummary
 * fuehren diese Felder - Foreground- und Nested-Eintraege lassen model/
 * thinking daher immer undefined, auch wenn der zugrundeliegende Agent
 * tatsaechlich mit einem bestimmten Modell laeuft.
 *
 * KNOWN GAP 7 (PHASE-06): asyncDir/pid (Voraussetzung fuer eine echte,
 * kanalbasierte Stop-Aktion) existieren strukturell nur auf der Async-
 * Parent-Zeile (job.asyncDir/job.pid bzw. run.asyncDir - AsyncRunSummary
 * fuehrt kein pid-Feld, dort bleibt pid daher immer undefined). Foreground-
 * und Nested-Eintraege sowie Async-Steps fuehren beide Felder nicht - deckt
 * sich mit canStop, das fuer all diese Quellen ohnehin false ist (siehe
 * subagent-executor.ts: action="stop" wird fuer foreground/nested explizit
 * abgelehnt, nur echte Async-Runs besitzen den dateibasierten Stop-Kanal
 * aus control-channel.ts).
 */

import { shortenPath } from "../../shared/formatters.ts";
import {
	type ActivityState,
	ASYNC_DIR,
	type AsyncJobState,
	type ForegroundControlState,
	type ForegroundResumeChild,
	type ForegroundResumeRun,
	type NestedRunSummary,
	type NestedStepSummary,
	RESULTS_DIR,
	type SubagentRunMode,
	type SubagentState,
} from "../../shared/types.ts";
import { childWatchdogIsActive, type ChildWatchdogStateSnapshot } from "../../watchdog/child-status.ts";
import { listAsyncRuns, type AsyncRunSummary } from "../background/async-status.ts";
import { updateAsyncJobNestedProjection, updateForegroundNestedProjection } from "./nested-events.ts";

export type FleetAgentState = "running" | "needs_attention" | "paused" | "stopped" | "completed" | "error";

export type FleetAttentionReason = "control_notice" | "watchdog_reviewing" | "watchdog_stalled" | "supervisor_pending";

/**
 * Strukturell kompatibler, lokal definierter Ersatz fuer das nicht
 * exportierte PendingSupervisorRequest aus native-supervisor-channel.ts
 * (diese Datei ist bewusste, unangetastete Baseline dieser Phase).
 */
export interface FleetPendingSupervisorRequest {
	runId: string;
	agent: string;
	childIndex: number;
	expectsReply: boolean;
	reason: string;
}

export interface FleetAgentEntry {
	key: string;
	runId: string;
	childIndex?: number;
	source: "foreground" | "async";
	kind: "active" | "recent";
	parentKey?: string;
	depth: number;

	agent: string;
	description?: string;
	mode?: SubagentRunMode;
	model?: string;
	thinking?: string;

	state: FleetAgentState;
	needsAttention: boolean;
	attentionReason?: FleetAttentionReason;
	canStop: boolean;
	asyncDir?: string;
	pid?: number;

	currentTool?: string;
	currentPath?: string;
	activityDetail?: string;

	startedAt: number;
	updatedAt: number;

	tokens?: number;
	tokenUsage?: { input: number; output: number; total: number };
	toolCount?: number;
	turnCount?: number;

	transcriptPath?: string;
	transcriptPathMaybeStale?: boolean;

	detached?: boolean;
}

type RawLifecycleState = "queued" | "pending" | "running" | "complete" | "completed" | "failed" | "paused" | "stopped" | "detached";

const RAW_STATE_MAP: Record<RawLifecycleState, FleetAgentState> = {
	queued: "running",
	pending: "running",
	running: "running",
	complete: "completed",
	completed: "completed",
	failed: "error",
	paused: "paused",
	stopped: "stopped",
	detached: "running",
};

/** Unbekannte Rohwerte fallen tolerant auf "running" zurueck statt zu werfen. */
export function mapRawStateToFleetState(raw: string): FleetAgentState {
	return RAW_STATE_MAP[raw as RawLifecycleState] ?? "running";
}

function isLiveRawState(raw: string): boolean {
	return raw === "running" || raw === "queued" || raw === "pending";
}

const STATE_SEVERITY: Record<FleetAgentState, number> = {
	error: 0,
	running: 1,
	needs_attention: 1,
	stopped: 2,
	paused: 3,
	completed: 4,
};

function pickWorstState(states: FleetAgentState[]): FleetAgentState {
	if (states.length === 0) return "completed";
	return states.reduce((worst, candidate) => (STATE_SEVERITY[candidate] < STATE_SEVERITY[worst] ? candidate : worst));
}

export interface AttentionInput {
	lifecycleTerminal: boolean;
	controlActivityState?: ActivityState;
	watchdogSnapshot?: ChildWatchdogStateSnapshot;
	hasPendingSupervisorRequest: boolean;
}

export interface AttentionResult {
	needsAttention: boolean;
	attentionReason?: FleetAttentionReason;
	stateOverride?: "error";
}

/**
 * Kombiniert control-notices, Watchdog-Snapshot und offene Supervisor-
 * Requests zu einem einzigen needsAttention/attentionReason-Ergebnis.
 * Terminal-Guard zuerst: ein bereits abgeschlossener/gestoppter/pausierter
 * Lauf "braucht keine Aufmerksamkeit mehr", auch wenn ein alter Watchdog-
 * Snapshot aus der letzten Aktivitaet vor Abschluss das nahelegen wuerde.
 */
export function resolveAttention(input: AttentionInput): AttentionResult {
	if (input.lifecycleTerminal) return { needsAttention: false };

	if (input.controlActivityState === "needs_attention") {
		return { needsAttention: true, attentionReason: "control_notice" };
	}

	const watchdog = input.watchdogSnapshot;
	if (watchdog) {
		if (watchdog.phase === "failed") {
			// Ein havarierter Watchdog eskaliert den State selbst zu "error", nicht nur
			// die Attention-Flag - die Supervision des Kindes ist gescheitert. Es teilt
			// sich den "watchdog_stalled"-Reason-Bucket mit stale/timedOut, da das
			// FleetAttentionReason-Vokabular bewusst keinen eigenen "failed"-Wert fuehrt.
			return { needsAttention: true, attentionReason: "watchdog_stalled", stateOverride: "error" };
		}
		if (watchdog.phase === "stale" || watchdog.timedOut) {
			return { needsAttention: true, attentionReason: "watchdog_stalled" };
		}
		if (childWatchdogIsActive(watchdog)) {
			return { needsAttention: true, attentionReason: "watchdog_reviewing" };
		}
	}

	if (input.hasPendingSupervisorRequest) {
		return { needsAttention: true, attentionReason: "supervisor_pending" };
	}

	return { needsAttention: false };
}

export interface ActivityDetailInput {
	currentTool?: string;
	currentPath?: string;
	watchdogSnapshot?: ChildWatchdogStateSnapshot;
	pendingSupervisorReason?: string;
	needsAttention: boolean;
	state: FleetAgentState;
}

/**
 * Informationspriroritaet fuer die konkrete Taetigkeitsanzeige. Erste
 * zutreffende Regel gewinnt; der generische Lifecycle-State ist bewusst
 * nur der letzte Fallback (Verifikationskriterium der Phase).
 */
export function pickActivityDetail(input: ActivityDetailInput): string | undefined {
	if (input.currentTool) {
		return input.currentPath ? `tool: ${input.currentTool} (${shortenPath(input.currentPath)})` : `tool: ${input.currentTool}`;
	}

	const watchdog = input.watchdogSnapshot;
	if (watchdog) {
		if (watchdog.phase === "stale" || watchdog.timedOut) return "watchdog: stalled";
		if (childWatchdogIsActive(watchdog)) return `watchdog: ${watchdog.phase}`;
	}

	if (input.pendingSupervisorReason) return `waiting: ${input.pendingSupervisorReason}`;
	if (input.needsAttention) return "needs attention";
	return input.state;
}

function findPendingRequest(pending: FleetPendingSupervisorRequest[], runId: string, childIndex?: number): FleetPendingSupervisorRequest | undefined {
	return pending.find(
		(request) => request.expectsReply && request.runId === runId && (childIndex === undefined || request.childIndex === childIndex),
	);
}

export interface ForegroundActiveContext {
	pending: FleetPendingSupervisorRequest[];
	now: number;
}

/**
 * Normalisiert die aktive Sammelzeile eines Foreground-Laufs (single,
 * parallel oder chain). Liefert bewusst nur EINE Zeile - siehe KNOWN GAP 2.
 */
export function normalizeForegroundActive(control: ForegroundControlState, ctx: ForegroundActiveContext): FleetAgentEntry {
	updateForegroundNestedProjection(control);

	const pendingRequest = findPendingRequest(ctx.pending, control.runId, control.currentIndex);
	const attention = resolveAttention({
		lifecycleTerminal: false,
		controlActivityState: control.currentActivityState,
		watchdogSnapshot: undefined, // KNOWN GAP 1
		hasPendingSupervisorRequest: Boolean(pendingRequest),
	});

	const state: FleetAgentState = attention.stateOverride ?? "running";
	const startedAt = control.startedAt;
	const updatedAt = control.updatedAt ?? control.lastActivityAt ?? startedAt;

	return {
		// Bewusst OHNE currentIndex im Key - der wechselt bei Parallel-/Chain-Laeufen
		// laufend ("wer zuletzt lief, gewinnt"), waehrend der Key stabil bleiben muss.
		key: `foreground:active:${control.runId}`,
		runId: control.runId,
		source: "foreground",
		kind: "active",
		depth: 0,
		agent: control.mode === "single" && control.currentAgent ? control.currentAgent : control.mode,
		mode: control.mode,
		state,
		needsAttention: attention.needsAttention,
		attentionReason: attention.attentionReason,
		canStop: typeof control.interrupt === "function",
		currentTool: control.currentTool,
		currentPath: control.currentPath,
		activityDetail: pickActivityDetail({
			currentTool: control.currentTool,
			currentPath: control.currentPath,
			watchdogSnapshot: undefined,
			pendingSupervisorReason: pendingRequest?.reason,
			needsAttention: attention.needsAttention,
			state,
		}),
		startedAt,
		updatedAt,
		tokens: control.tokens,
		toolCount: control.toolCount,
		turnCount: control.turnCount,
	};
}

/**
 * Normalisiert einen kuerzlich abgeschlossenen Foreground-Lauf (Parent- +
 * Kind-Zeilen). Bereits aktive runIds werden uebersprungen (kein Duplikat
 * zur aktiven Zeile). KNOWN GAP 4 (kein startedAt) und KNOWN GAP 5 (keine
 * Nested-Kinder) gelten hier.
 */
export function normalizeForegroundRecent(run: ForegroundResumeRun, activeRunIds: Set<string>): FleetAgentEntry[] {
	if (activeRunIds.has(run.runId)) return [];

	const parentKey = `foreground:recent:${run.runId}`;
	const childEntries = run.children.map((child) => normalizeForegroundRecentChild(child, run, parentKey));
	const worstState = pickWorstState(childEntries.map((entry) => entry.state));

	const parentEntry: FleetAgentEntry = {
		key: parentKey,
		runId: run.runId,
		source: "foreground",
		kind: "recent",
		depth: 0,
		agent: run.mode,
		mode: run.mode,
		state: worstState,
		needsAttention: false,
		canStop: false,
		startedAt: run.updatedAt, // KNOWN GAP 4
		updatedAt: run.updatedAt,
	};

	return [parentEntry, ...childEntries];
}

function normalizeForegroundRecentChild(child: ForegroundResumeChild, run: ForegroundResumeRun, parentKey: string): FleetAgentEntry {
	const state = mapRawStateToFleetState(child.status);
	const updatedAt = child.updatedAt ?? run.updatedAt;

	return {
		key: `${parentKey}:${child.index}`,
		runId: run.runId,
		childIndex: child.index,
		source: "foreground",
		kind: "recent",
		parentKey,
		depth: 1,
		agent: child.agent,
		mode: run.mode,
		state,
		needsAttention: false,
		canStop: false,
		startedAt: updatedAt, // KNOWN GAP 4
		updatedAt,
		transcriptPath: child.transcriptPath,
		detached: child.status === "detached",
	};
}

interface AsyncStepInput {
	runId: string;
	parentKey: string;
	index: number;
	agent: string;
	status: string;
	activityState?: ActivityState;
	watchdog?: ChildWatchdogStateSnapshot;
	currentTool?: string;
	currentPath?: string;
	turnCount?: number;
	toolCount?: number;
	tokens?: { input: number; output: number; total: number };
	startedAt?: number;
	endedAt?: number;
	lastActivityAt?: number;
	transcriptPath?: string;
	transcriptPathMaybeStale?: boolean;
	model?: string;
	thinking?: string;
	now: number;
}

function normalizeAsyncStep(input: AsyncStepInput): FleetAgentEntry {
	const baseState = mapRawStateToFleetState(input.status);
	const terminal = baseState === "completed" || baseState === "error" || baseState === "stopped" || baseState === "paused";
	const attention = resolveAttention({
		lifecycleTerminal: terminal,
		controlActivityState: input.activityState,
		watchdogSnapshot: input.watchdog,
		hasPendingSupervisorRequest: false,
	});
	const state = attention.stateOverride ?? baseState;
	const updatedAt = input.lastActivityAt ?? input.endedAt ?? input.startedAt ?? input.now;
	const startedAt = input.startedAt ?? updatedAt;

	return {
		key: `${input.parentKey}:${input.index}`,
		runId: input.runId,
		childIndex: input.index,
		source: "async",
		kind: isLiveRawState(input.status) ? "active" : "recent",
		parentKey: input.parentKey,
		depth: 1,
		agent: input.agent,
		state,
		needsAttention: attention.needsAttention,
		attentionReason: attention.attentionReason,
		canStop: false,
		currentTool: input.currentTool,
		currentPath: input.currentPath,
		activityDetail: pickActivityDetail({
			currentTool: input.currentTool,
			currentPath: input.currentPath,
			watchdogSnapshot: input.watchdog,
			pendingSupervisorReason: undefined,
			needsAttention: attention.needsAttention,
			state,
		}),
		startedAt,
		updatedAt,
		tokens: input.tokens?.total,
		tokenUsage: input.tokens,
		toolCount: input.toolCount,
		turnCount: input.turnCount,
		transcriptPath: input.transcriptPath,
		transcriptPathMaybeStale: input.transcriptPathMaybeStale,
		model: input.model,
		thinking: input.thinking,
	};
}

export interface AsyncActiveContext {
	pending: FleetPendingSupervisorRequest[];
	now: number;
}

/**
 * Normalisiert einen Eintrag aus state.asyncJobs (frisch, in-memory).
 * kind wird pro Eintrag aus dem tatsaechlichen Rohstatus abgeleitet, nicht
 * aus der Herkunfts-Map - abgeschlossene Jobs verbleiben bis zu 10s nach
 * Abschluss in state.asyncJobs (completionRetentionMs, scheduleCleanup()).
 */
export function normalizeAsyncJobState(job: AsyncJobState, ctx: AsyncActiveContext): FleetAgentEntry[] {
	updateAsyncJobNestedProjection(job);

	const parentKey = `async:${job.asyncId}`;
	const pendingRequest = findPendingRequest(ctx.pending, job.asyncId);
	const attention = resolveAttention({
		lifecycleTerminal: !isLiveRawState(job.status),
		controlActivityState: job.activityState,
		watchdogSnapshot: undefined, // KNOWN GAP 1: kein Job-Level-Watchdog, nur pro Step.
		hasPendingSupervisorRequest: Boolean(pendingRequest),
	});
	const state = attention.stateOverride ?? mapRawStateToFleetState(job.status);
	const updatedAt = job.updatedAt ?? job.startedAt ?? ctx.now;
	const startedAt = job.startedAt ?? updatedAt;

	const parentEntry: FleetAgentEntry = {
		key: parentKey,
		runId: job.asyncId,
		source: "async",
		kind: isLiveRawState(job.status) ? "active" : "recent",
		depth: 0,
		agent: job.mode === "single" && job.agents?.[0] ? job.agents[0] : (job.mode ?? "async"),
		mode: job.mode,
		state,
		needsAttention: attention.needsAttention,
		attentionReason: attention.attentionReason,
		canStop: isLiveRawState(job.status),
		asyncDir: job.asyncDir,
		pid: job.pid,
		currentTool: job.currentTool,
		currentPath: job.currentPath,
		activityDetail: pickActivityDetail({
			currentTool: job.currentTool,
			currentPath: job.currentPath,
			watchdogSnapshot: undefined,
			pendingSupervisorReason: pendingRequest?.reason,
			needsAttention: attention.needsAttention,
			state,
		}),
		startedAt,
		updatedAt,
		tokens: job.totalTokens?.total,
		tokenUsage: job.totalTokens,
		toolCount: job.toolCount,
		turnCount: job.turnCount,
	};

	const stepEntries = (job.steps ?? []).map((step, index) =>
		normalizeAsyncStep({
			runId: job.asyncId,
			parentKey,
			index: step.index ?? index,
			agent: step.agent,
			status: step.status,
			activityState: step.activityState,
			watchdog: step.watchdog,
			currentTool: step.currentTool,
			currentPath: step.currentPath,
			turnCount: step.turnCount,
			toolCount: step.toolCount,
			tokens: step.tokens,
			startedAt: step.startedAt,
			endedAt: step.endedAt,
			lastActivityAt: step.lastActivityAt,
			transcriptPath: step.transcriptPath,
			transcriptPathMaybeStale: false,
			model: step.model,
			thinking: step.thinking,
			now: ctx.now,
		}),
	);

	return [parentEntry, ...stepEntries];
}

/**
 * Normalisiert einen Eintrag aus listAsyncRuns() (Disk-Scan). Wird nur fuer
 * asyncIds verwendet, die NICHT bereits in state.asyncJobs stehen (Dedupe
 * durch den Aufrufer) - noetig, weil abgeschlossene Jobs dort nach 10s
 * verschwinden (kind:"recent" jenseits dieses Fensters kommt ausschliesslich
 * von hier). KNOWN GAP 3 gilt fuer alle Step-Zeilen dieser Funktion.
 */
export function normalizeAsyncRunSummary(run: AsyncRunSummary, ctx: { now: number }): FleetAgentEntry[] {
	const attention = resolveAttention({
		lifecycleTerminal: !isLiveRawState(run.state),
		controlActivityState: run.activityState,
		watchdogSnapshot: undefined,
		hasPendingSupervisorRequest: false,
	});
	const state = attention.stateOverride ?? mapRawStateToFleetState(run.state);
	const updatedAt = run.lastUpdate ?? run.startedAt ?? ctx.now;
	const parentKey = `async:${run.id}`;

	const parentEntry: FleetAgentEntry = {
		key: parentKey,
		runId: run.id,
		source: "async",
		kind: isLiveRawState(run.state) ? "active" : "recent",
		depth: 0,
		agent: run.mode === "single" && run.steps[0]?.agent ? run.steps[0].agent : run.mode,
		mode: run.mode,
		state,
		needsAttention: attention.needsAttention,
		attentionReason: attention.attentionReason,
		canStop: isLiveRawState(run.state),
		asyncDir: run.asyncDir,
		currentTool: run.currentTool,
		currentPath: run.currentPath,
		activityDetail: pickActivityDetail({
			currentTool: run.currentTool,
			currentPath: run.currentPath,
			watchdogSnapshot: undefined,
			pendingSupervisorReason: undefined,
			needsAttention: attention.needsAttention,
			state,
		}),
		startedAt: run.startedAt,
		updatedAt,
		tokens: run.totalTokens?.total,
		tokenUsage: run.totalTokens,
		toolCount: run.toolCount,
		turnCount: run.turnCount,
	};

	const terminal = state === "completed" || state === "error" || state === "stopped" || state === "paused";
	const stepEntries = run.steps.map((step, index) =>
		normalizeAsyncStep({
			runId: run.id,
			parentKey,
			index,
			agent: step.agent,
			status: step.status,
			activityState: step.activityState,
			watchdog: undefined, // KNOWN GAP 3
			currentTool: step.currentTool,
			currentPath: step.currentPath,
			turnCount: step.turnCount,
			toolCount: step.toolCount,
			tokens: step.tokens,
			startedAt: undefined,
			endedAt: undefined,
			lastActivityAt: step.lastActivityAt,
			transcriptPath: undefined, // KNOWN GAP 3
			transcriptPathMaybeStale: terminal,
			model: step.model,
			thinking: step.thinking,
			now: ctx.now,
		}),
	);

	return [parentEntry, ...stepEntries];
}

interface NestedContext {
	now: number;
	source: "foreground" | "async";
	rootRunId: string;
}

const NESTED_MAX_DEPTH = 3; // mirrors MAX_DEPTH in nested-events.ts (nicht re-exportiert).

function isLiveNestedState(state: NestedRunSummary["state"]): boolean {
	return state === "running" || state === "queued";
}

/**
 * Normalisiert einen Nested-Run rekursiv (bis NESTED_MAX_DEPTH), liefert
 * aber eine FLACHE Liste (Run-Zeile + Step-Zeilen + rekursive Kind-Zeilen).
 * runId bleibt ueber die gesamte Rekursion die des Wurzel-Laufs (ctx.rootRunId),
 * NICHT run.parentRunId, das sich pro Ebene aendert.
 */
export function normalizeNestedRun(run: NestedRunSummary, parentKey: string, depth: number, ctx: NestedContext): FleetAgentEntry[] {
	if (depth > NESTED_MAX_DEPTH) return [];

	const key = `nested:${run.id}`;
	const terminal = run.state === "complete" || run.state === "failed" || run.state === "paused" || run.state === "stopped";
	const lastStepWatchdog = run.steps?.length ? run.steps[run.steps.length - 1]?.watchdog : undefined;
	const attention = resolveAttention({
		lifecycleTerminal: terminal,
		controlActivityState: run.activityState,
		watchdogSnapshot: lastStepWatchdog,
		hasPendingSupervisorRequest: false,
	});
	const state = attention.stateOverride ?? mapRawStateToFleetState(run.state);
	const updatedAt = run.lastUpdate ?? run.endedAt ?? run.startedAt ?? ctx.now;
	const startedAt = run.startedAt ?? updatedAt;

	const entry: FleetAgentEntry = {
		key,
		runId: ctx.rootRunId,
		source: ctx.source,
		kind: isLiveNestedState(run.state) ? "active" : "recent",
		parentKey,
		depth,
		agent: run.agent ?? run.mode ?? "nested",
		mode: run.mode,
		state,
		needsAttention: attention.needsAttention,
		attentionReason: attention.attentionReason,
		canStop: false,
		currentTool: run.currentTool,
		currentPath: run.currentPath,
		activityDetail: pickActivityDetail({
			currentTool: run.currentTool,
			currentPath: run.currentPath,
			watchdogSnapshot: lastStepWatchdog,
			pendingSupervisorReason: undefined,
			needsAttention: attention.needsAttention,
			state,
		}),
		startedAt,
		updatedAt,
		tokens: run.totalTokens?.total,
		tokenUsage: run.totalTokens,
		toolCount: run.toolCount,
		turnCount: run.turnCount,
	};

	const stepEntries = (run.steps ?? []).flatMap((step, index) => normalizeNestedStep(step, key, index, depth + 1, ctx));
	const childRunEntries = (run.children ?? []).flatMap((child) => normalizeNestedRun(child, key, depth + 1, ctx));

	return [entry, ...stepEntries, ...childRunEntries];
}

function normalizeNestedStep(step: NestedStepSummary, parentKey: string, index: number, depth: number, ctx: NestedContext): FleetAgentEntry[] {
	const stepKey = `${parentKey}:step:${index}`;
	const terminal = step.status === "complete" || step.status === "completed" || step.status === "failed" || step.status === "paused" || step.status === "stopped";
	const attention = resolveAttention({
		lifecycleTerminal: terminal,
		controlActivityState: step.activityState,
		watchdogSnapshot: step.watchdog,
		hasPendingSupervisorRequest: false,
	});
	const state = attention.stateOverride ?? mapRawStateToFleetState(step.status);
	const updatedAt = step.lastActivityAt ?? step.endedAt ?? step.startedAt ?? ctx.now;
	const startedAt = step.startedAt ?? updatedAt;

	const entry: FleetAgentEntry = {
		key: stepKey,
		runId: ctx.rootRunId,
		source: ctx.source,
		// Nested-Steps haben kein eigenes id-Feld - Index-basierter Pseudo-Key, stabil
		// solange Chain-Step-Arrays append-only/positionsfest bleiben (Annahme, siehe Doku-Kopf).
		kind: step.status === "running" || step.status === "pending" ? "active" : "recent",
		parentKey,
		depth,
		agent: step.agent,
		state,
		needsAttention: attention.needsAttention,
		attentionReason: attention.attentionReason,
		canStop: false,
		currentTool: step.currentTool,
		currentPath: step.currentPath,
		activityDetail: pickActivityDetail({
			currentTool: step.currentTool,
			currentPath: step.currentPath,
			watchdogSnapshot: step.watchdog,
			pendingSupervisorReason: undefined,
			needsAttention: attention.needsAttention,
			state,
		}),
		startedAt,
		updatedAt,
		transcriptPath: step.transcriptPath,
	};

	const childEntries = (step.children ?? []).flatMap((child) => normalizeNestedRun(child, stepKey, depth + 1, ctx));
	return [entry, ...childEntries];
}

export interface BuildFleetEntriesDeps {
	asyncDirRoot?: string;
	resultsDir?: string;
	pending?: FleetPendingSupervisorRequest[];
	now?: () => number;
	recentAsyncLimit?: number;
}

const DEFAULT_RECENT_ASYNC_LIMIT = 20;

/**
 * Haupt-Entrypoint: baut die vollstaendige, flache FleetAgentEntry-Liste aus
 * allen Runtime-Quellen (Foreground aktiv/recent, Async aktiv/recent,
 * Nested-Kinder beider Wurzeln).
 */
export function buildFleetEntries(state: SubagentState, deps: BuildFleetEntriesDeps = {}): FleetAgentEntry[] {
	const now = deps.now?.() ?? Date.now();
	const pending = deps.pending ?? [];
	const entries: FleetAgentEntry[] = [];

	const activeRunIds = new Set(state.foregroundControls.keys());
	for (const control of state.foregroundControls.values()) {
		const activeEntry = normalizeForegroundActive(control, { pending, now });
		entries.push(activeEntry);
		for (const child of control.nestedChildren ?? []) {
			entries.push(...normalizeNestedRun(child, activeEntry.key, 1, { now, source: "foreground", rootRunId: control.runId }));
		}
	}

	for (const run of state.foregroundRuns?.values() ?? []) {
		entries.push(...normalizeForegroundRecent(run, activeRunIds));
	}

	for (const job of state.asyncJobs.values()) {
		const jobEntries = normalizeAsyncJobState(job, { pending, now });
		entries.push(...jobEntries);
		const parentEntry = jobEntries[0];
		for (const child of job.nestedChildren ?? []) {
			entries.push(...normalizeNestedRun(child, parentEntry.key, 1, { now, source: "async", rootRunId: job.asyncId }));
		}
	}

	const knownAsyncIds = new Set(state.asyncJobs.keys());
	let recentRuns: AsyncRunSummary[] = [];
	try {
		recentRuns = listAsyncRuns(deps.asyncDirRoot ?? ASYNC_DIR, {
			states: ["complete", "failed", "paused", "stopped"],
			sessionId: state.currentSessionId ?? undefined,
			resultsDir: deps.resultsDir ?? RESULTS_DIR,
			limit: deps.recentAsyncLimit ?? DEFAULT_RECENT_ASYNC_LIMIT,
		});
	} catch {
		// Ein Disk-Scan-Fehler liefert still eine leere recent-Liste statt zu werfen -
		// vertretbar fuer eine reine Anzeige-Projektionsschicht.
		recentRuns = [];
	}
	for (const run of recentRuns) {
		if (knownAsyncIds.has(run.id)) continue;
		const runEntries = normalizeAsyncRunSummary(run, { now });
		entries.push(...runEntries);
		const parentEntry = runEntries[0];
		for (const child of run.nestedChildren ?? []) {
			entries.push(...normalizeNestedRun(child, parentEntry.key, 1, { now, source: "async", rootRunId: run.id }));
		}
	}

	return entries;
}

/**
 * Fleet Status Dock – Rendering (PHASE-04, Aurora-Politur in PHASE-08).
 *
 * Reine Renderfunktion: FleetAgentEntry[] -> string[]. Kein I/O, kein
 * eigener Zustand (Auswahl/Expansion werden vom Aufrufer als Parameter
 * uebergeben). Analog zu buildWidgetLines() im alten Async-Widget
 * (../tui/render.ts), aber unabhaengig vom AsyncJobState-Typ.
 *
 * PHASE-06: needs_attention sortiert jetzt strikt vor running (eigener Rang,
 * nicht mehr gleichrangig+updatedAt-Tiebreak) - ein Attention-Eintrag soll
 * nicht mehr rein durch Alter unter die MAX_DOCK_ROWS-Sichtgrenze rutschen
 * und unmarkiert in der "+N weitere"-Zeile verschwinden koennen. Die
 * Aktivitaetszeile eines needsAttention-Eintrags wird zusaetzlich in
 * "warning" statt "dim" gerendert, statt sich allein auf das ⚠-Glyphenzeichen
 * zu verlassen.
 *
 * PHASE-08 (Aurora-UI, Darstellung - kein Verhaltenswechsel):
 * 1. Jeder Zustand hat ein EIGENES Glyphenzeichen. Vorher teilten sich
 *    paused und stopped "■" in derselben Farbe und waren damit ohne
 *    Farbunterscheidung ununterscheidbar - die Regel "Status nicht
 *    ausschliesslich ueber Farbe kommunizieren" war faktisch verletzt.
 *    Zusaetzlich traegt jeder Nicht-Running-Zustand ein ausgeschriebenes
 *    Textlabel in der Statuszeile.
 * 2. Die Auswahl wird ueber drei redundante Kanaele markiert: "›"-Praefix
 *    (Glyphe), Akzentfarbe und Fettdruck.
 * 3. Feste Namensspalte je Terminalbreite (nameColumnWidth) statt frei
 *    fliessender Namen: die Aktivitaetsspalte beginnt dadurch in jeder Zeile an
 *    derselben Stelle und wandert nicht mit der Namenslaenge.
 * 4. Budgetbasierte Kuerzung statt reinem Zeilenende-Abschnitt: Laufzeit und
 *    Tokenzahl sind fixe Bestandteile und ueberleben immer; nur die
 *    Aktivitaetsbeschreibung wird auf das verbleibende Budget gekuerzt.
 *    Pfade darin werden ueber compactPath() auf die letzten beiden Segmente
 *    eingedampft ("…/plan-mode/index.ts") statt am Zeilenende abgeschnitten.
 * 5. Kopfzeile mit Zaehlern und - nur bei Tastaturfokus - eine Zeile mit den
 *    tatsaechlich verfuegbaren Tastenkuerzeln (siehe CONCEPT.md-Zielbild).
 *    Ohne Fokus entfaellt die Kuerzelzeile und die Hinweise "↓ select" und
 *    "Super+↓ jump" (PHASE-09: bewusstes, editorunabhaengiges Kuerzel, siehe
 *    fleet-dock-controller.ts) stehen stattdessen in der Kopfzeile - der
 *    Fussabdruck waechst gegenueber PHASE-04 damit auch ohne Fokus um genau
 *    die eine Kopfzeile.
 *
 * PHASE-09 (Uebersichtlichkeit, Nutzerfeedback nach Live-Einsatz):
 * 1. Laufzeit und Tokenzahl standen bisher direkt hinter der
 *    Aktivitaetsbeschreibung und damit je nach deren Laenge an einer anderen
 *    Spaltenposition - senkrechtes Scannen/Vergleichen war nicht moeglich.
 *    Beide Werte stehen jetzt in einer eigenen, fest breiten,
 *    rechtsbuendigen Spalte (statsBlockText()) am Zeilenende, unabhaengig von
 *    der Aktivitaetstextlaenge und der Verschachtelungstiefe (siehe Punkt 3).
 *    Ersetzt die widersprochene Aussage aus PHASE-08-Punkt 3 oben.
 * 2. Zwischen Namensspalte und Mittelteil steht jetzt eine reine
 *    Leerraum-Luecke statt eines "·"-Trenners - eine Trennzeichenebene
 *    weniger pro Zeile fuer mehr visuelle Ruhe.
 * 3. Verschachtelte Eintraege (entry.depth > 0, von einem anderen Agenten
 *    gestartet) werden um zwei Leerzeichen pro Ebene eingerueckt (INDENT_UNIT)
 *    - die Eltern/Kind-Hierarchie ist damit direkt im Dock sichtbar, nicht
 *    mehr nur in der "children:"-Liste des Inspectors. Die Statsspalte bleibt
 *    dabei unveraendert am selben Zeilenende ausgerichtet (die Einrueckung
 *    geht zulasten des Mittelteil-Budgets, nicht der Statsspalte).
 *
 * Bewusst NICHT enthalten: Spinner, Ticker oder sonstige Animationen. Das
 * Dock rendert ausschliesslich aus dem uebergebenen Zustand (Anforderung
 * "Kein permanenter schneller Spinner fuer jede Agentenzeile").
 */

import type { ExtensionContext } from "@earendil-works/pi-coding-agent";
import { formatDuration, formatTokens, shortenPath } from "../shared/formatters.ts";
import type { FleetAgentEntry, FleetAgentState } from "../runs/shared/fleet-projection.ts";
import { themeBold, truncLine } from "./render.ts";

type Theme = ExtensionContext["ui"]["theme"];
type ThemeColor = Parameters<Theme["fg"]>[0];

export const MAX_DOCK_ROWS = 6;

/** Mindestbreite, unterhalb derer die Aktivitaetsbeschreibung ganz entfaellt statt zu einem Stummel zu werden. */
const MIN_DETAIL_WIDTH = 10;

const SEPARATOR = " · ";

// Sortier-Rang: needs_attention zuerst, dann running, dann paused, dann alle
// Terminalzustaende zuletzt.
const STATE_RANK: Record<FleetAgentState, number> = {
	needs_attention: 0,
	running: 1,
	paused: 2,
	completed: 3,
	error: 3,
	stopped: 3,
};

const TERMINAL_STATES: ReadonlySet<FleetAgentState> = new Set(["completed", "error", "stopped"]);

interface StateVisual {
	glyph: string;
	color: ThemeColor;
	/**
	 * Ausgeschriebener Zustand fuer die Statuszeile. Bewusst nicht fuer
	 * running (dort traegt die konkrete Taetigkeit die Information, siehe
	 * CONCEPT.md "Generische Ausgaben wie 'arbeitet' sind kein ausreichender
	 * Primaerstatus") und nicht fuer needs_attention (dort steht der Grund
	 * bereits in activityDetail).
	 */
	label?: string;
}

const STATE_VISUALS: Record<FleetAgentState, StateVisual> = {
	needs_attention: { glyph: "⚠", color: "warning" },
	running: { glyph: "●", color: "accent" },
	paused: { glyph: "‖", color: "warning", label: "paused" },
	stopped: { glyph: "■", color: "muted", label: "stopped" },
	completed: { glyph: "✓", color: "success", label: "done" },
	error: { glyph: "✗", color: "error", label: "error" },
};

export function sortFleetEntries(entries: FleetAgentEntry[]): FleetAgentEntry[] {
	return [...entries].sort((a, b) => {
		const rankDiff = STATE_RANK[a.state] - STATE_RANK[b.state];
		if (rankDiff !== 0) return rankDiff;
		return b.updatedAt - a.updatedAt;
	});
}

/**
 * Nachschlag mit Rueckfall. Die Vorgaengerfassung endete auf einem else-Zweig
 * und war damit total; ein Record-Zugriff waere es bei einem Zustandswert
 * ausserhalb der sechs bekannten nicht (TypeError beim Farbzugriff).
 */
function stateVisual(state: FleetAgentState): StateVisual {
	return STATE_VISUALS[state] ?? { glyph: "✗", color: "error", label: String(state) };
}

export function stateGlyph(state: FleetAgentState, theme: Theme): string {
	const visual = stateVisual(state);
	return theme.fg(visual.color, visual.glyph);
}

/**
 * Breite der festen Namensspalte. Skaliert mit der Terminalbreite, bleibt
 * aber fuer eine gegebene Breite konstant - dadurch stehen die Statusspalten
 * stabil untereinander, unabhaengig davon welche Agenten gerade laufen.
 * 80 -> 16, 120 -> 24, 160 -> 24 (gedeckelt).
 */
export function nameColumnWidth(width: number): number {
	return Math.max(12, Math.min(24, Math.floor(width * 0.2)));
}

/**
 * Kuerzt einen Pfad auf die letzten Segmente statt ihn am Zeilenende
 * abzuschneiden - der Dateiname ist die informationstragende Haelfte.
 */
export function compactPath(path: string, maxSegments = 2): string {
	const shortened = shortenPath(path);
	const segments = shortened.split("/").filter((segment) => segment.length > 0);
	if (segments.length <= maxSegments) return shortened;
	return `…/${segments.slice(-maxSegments).join("/")}`;
}

/** Ersetzt einen in Klammern eingebetteten Pfad (siehe pickActivityDetail) durch seine Kurzform. */
export function compactActivityDetail(detail: string): string {
	return detail.replace(/\(([^()]*\/[^()]*)\)/, (_match, path: string) => `(${compactPath(path)})`);
}

function fitDetail(detail: string, budget: number): string | undefined {
	const compact = compactActivityDetail(detail);
	if (compact.length <= budget) return compact;
	if (budget < MIN_DETAIL_WIDTH) return undefined;
	return `${compact.slice(0, budget - 1)}…`;
}

function fitName(name: string, cell: number): string {
	if (name.length > cell) return `${name.slice(0, Math.max(1, cell - 1))}…`;
	return name.padEnd(cell, " ");
}

/**
 * Feste, rechtsbuendige Statsspalte (Laufzeit · Tokens). PHASE-09: vorher
 * folgten Laufzeit und Tokenzahl direkt auf die Aktivitaetsbeschreibung und
 * standen dadurch in jeder Zeile an einer anderen Spaltenposition -
 * senkrechtes Scannen/Vergleichen war nicht moeglich (Nutzerfeedback). Beide
 * Werte werden jetzt einzeln auf eine feste Breite rechtsbuendig aufgefuellt,
 * sodass ihre Ziffern in jeder Zeile an derselben Stelle stehen, unabhaengig
 * von der Laenge der Aktivitaetsbeschreibung davor.
 */
const STATS_DURATION_WIDTH = 6;
const STATS_TOKENS_WIDTH = 5;
const STATS_BLOCK_WIDTH = STATS_DURATION_WIDTH + SEPARATOR.length + STATS_TOKENS_WIDTH;
const STATS_GAP = 2;

/** Zwei Leerzeichen pro Verschachtelungsebene (PHASE-09: sichtbare Eltern/Kind-Hierarchie im Dock selbst, nicht nur im Inspector). */
const INDENT_UNIT = "  ";

function statsBlockText(entry: FleetAgentEntry, now: number): string {
	const duration = formatDuration(Math.max(0, now - entry.startedAt)).padStart(STATS_DURATION_WIDTH, " ");
	const tokenTotal = entry.tokens ?? entry.tokenUsage?.total;
	const tokens = (tokenTotal !== undefined ? formatTokens(tokenTotal) : "").padStart(STATS_TOKENS_WIDTH, " ");
	return `${duration}${SEPARATOR}${tokens}`;
}

/**
 * Baut den linksbuendigen Mittelteil (Textlabel + Aktivitaetsbeschreibung).
 * Laufzeit/Tokens sind hier bewusst NICHT mehr enthalten (siehe statsBlockText).
 */
function middleZoneText(entry: FleetAgentEntry, budget: number): string {
	const visual = stateVisual(entry.state);
	const fixed: string[] = [];
	if (visual.label) fixed.push(visual.label);

	// pickActivityDetail() faellt ohne konkrete Taetigkeit auf den State-Namen
	// selbst zurueck - zusammen mit dem Textlabel ergaebe das "stopped · stopped".
	const rawDetail = entry.activityDetail ? entry.activityDetail : undefined;
	const meaningfulDetail = rawDetail !== undefined && rawDetail !== entry.state ? rawDetail : undefined;

	const fixedLength = fixed.reduce((sum, part) => sum + part.length + SEPARATOR.length, 0);
	const detail = meaningfulDetail !== undefined ? fitDetail(meaningfulDetail, budget - fixedLength) : undefined;

	const parts = [...fixed];
	if (detail !== undefined) parts.push(detail);
	// running ohne konkrete Taetigkeit hat weder Label noch Detail - dann bleibt
	// der rohe Zustand als schwaechste Stufe der Informationsprioritaet stehen.
	// Gleiches gilt, wenn das Budget fuer eine sinnvolle Kuerzung nicht reicht
	// (sehr schmale Terminals): lieber die eingedampfte Beschreibung zeigen und
	// truncLine() den Rest erledigen lassen als eine leere Mittelspalte.
	if (parts.length === 0 && rawDetail !== undefined) parts.push(compactActivityDetail(rawDetail));
	return parts.join(SEPARATOR);
}

export function entryLine(entry: FleetAgentEntry, isSelected: boolean, now: number, theme: Theme, width: number): string {
	const nameCell = nameColumnWidth(width);
	const indent = INDENT_UNIT.repeat(entry.depth);
	const prefix = isSelected ? theme.fg("accent", "› ") : "  ";
	const glyph = stateGlyph(entry.state, theme);
	const nameText = fitName(entry.agent, nameCell);
	// Auswahl redundant markiert: Glyphe (›), Farbe (accent) und Fettdruck.
	const name = themeBold(theme, isSelected ? theme.fg("accent", nameText) : nameText);

	const fixedLeftWidth = 2 /* Praefix */ + indent.length + 2 /* Glyphe + Leerzeichen */ + nameCell + 2 /* Luecke nach Namen */;
	const middleBudget = Math.max(0, width - fixedLeftWidth - STATS_BLOCK_WIDTH - STATS_GAP);

	// PHASE-06: needsAttention faerbt Mittelteil und Statsspalte "warning" statt
	// "dim" - das Glyphenzeichen allein reicht nicht als deutliche Anzeige.
	const partColor = entry.needsAttention ? "warning" : "dim";
	const middleText = middleZoneText(entry, middleBudget);
	// Auffuellung bewusst AUSSERHALB des theme.fg()-Aufrufs: die Farbmarkierung
	// umschliesst nur den sichtbaren Text, nicht die reinen Fuellzeichen davor
	// der Statsspalte.
	const middlePadding = " ".repeat(Math.max(0, middleBudget - middleText.length));
	const middle = `${theme.fg(partColor, middleText)}${middlePadding}`;
	const stats = theme.fg(partColor, statsBlockText(entry, now));

	return truncLine(`${prefix}${indent}${glyph} ${name}  ${middle}${" ".repeat(STATS_GAP)}${stats}`, width);
}

function detailLines(entry: FleetAgentEntry, theme: Theme, width: number): string[] {
	// PHASE-09: folgt der Einrueckung der Eintragszeile selbst, damit
	// aufgeklappte Details sichtbar unter einem eingerueckten Kind-Eintrag
	// stehen statt immer auf dieselbe Spalte zurueckzufallen.
	const indent = `      ${INDENT_UNIT.repeat(entry.depth)}`;
	const lines: string[] = [];
	// Wie in middleZoneText(): der reine State-Fallback aus pickActivityDetail()
	// ist hier keine zusaetzliche Information (das Glyphenzeichen und das
	// Textlabel der Statuszeile sagen dasselbe).
	if (entry.activityDetail && entry.activityDetail !== entry.state) {
		lines.push(truncLine(theme.fg("dim", `${indent}⎿  ${compactActivityDetail(entry.activityDetail)}`), width));
	}
	if (entry.tokenUsage) {
		lines.push(
			truncLine(
				theme.fg("dim", `${indent}tokens: ${formatTokens(entry.tokenUsage.input)} in / ${formatTokens(entry.tokenUsage.output)} out`),
				width,
			),
		);
	}
	if (entry.transcriptPath) {
		const staleSuffix = entry.transcriptPathMaybeStale ? " (moeglicherweise veraltet)" : "";
		lines.push(truncLine(theme.fg("dim", `${indent}transcript: ${compactPath(entry.transcriptPath, 3)}${staleSuffix}`), width));
	}
	return lines;
}

export interface RenderFleetDockOptions {
	width: number;
	theme: Theme;
	expandedKey?: string;
	maxRows?: number;
	now?: number;
	// PHASE-06: Key eines Eintrags mit ausstehender Stop-Bestaetigung (erstes
	// "s" wurde gedrueckt). Rendert eine explizite Bestaetigungszeile direkt
	// unter dem betroffenen Eintrag.
	stopArmedKey?: string;
	// PHASE-08: true, waehrend das Dock Tastaturfokus haelt
	// (FleetDockController.isActive()). Nur dann wird die Tastenkuerzelzeile
	// gerendert - ohne Fokus waere sie irrefuehrend und kostet nur Hoehe.
	active?: boolean;
}

function stopConfirmLine(entry: FleetAgentEntry, theme: Theme, width: number): string {
	const indent = `      ${INDENT_UNIT.repeat(entry.depth)}`;
	return truncLine(theme.fg("warning", `${indent}Stop bestaetigen: erneut 's' druecken (Escape zum Abbrechen)`), width);
}

/**
 * Kopfzeile mit Zaehlern (CONCEPT.md-Zielbild: "AGENTS · 2 active · 1 needs
 * attention"). Der Attention-Zaehler erscheint nur, wenn es tatsaechlich einen
 * gibt, und wird als einziges Segment in "warning" gerendert.
 */
export function dockHeaderLine(entries: FleetAgentEntry[], theme: Theme, width: number, active: boolean): string {
	const activeCount = entries.filter((entry) => !TERMINAL_STATES.has(entry.state)).length;
	const attentionCount = entries.filter((entry) => entry.needsAttention || entry.state === "needs_attention").length;
	const segments = [theme.fg("dim", "AGENTS"), theme.fg("dim", `${activeCount} active`)];
	if (attentionCount > 0) segments.push(theme.fg("warning", `${attentionCount} needs attention`));
	if (!active) segments.push(theme.fg("dim", "↓ select"), theme.fg("dim", "Super+↓ jump"));
	const dot = theme.fg("dim", "·");
	return truncLine(`  ${segments.join(` ${dot} `)}`, width);
}

/**
 * Tastenkuerzelzeile. Zeigt nur Kuerzel, die auf den aktuell ausgewaehlten
 * Eintrag auch tatsaechlich wirken - dieselben Bedingungen wie im
 * FleetDockController (stop nur fuer stoppbare Async-Laeufe, dismiss nur fuer
 * terminale Top-Level-Eintraege).
 */
export function dockHintLine(selected: FleetAgentEntry | undefined, theme: Theme, width: number): string {
	const hints = ["↑↓ select", "enter inspect"];
	if (selected && selected.source === "async" && selected.canStop && selected.asyncDir) hints.push("s stop");
	if (selected && selected.depth === 0 && TERMINAL_STATES.has(selected.state)) hints.push("d dismiss");
	hints.push("esc back");
	return truncLine(theme.fg("dim", `  ${hints.join(SEPARATOR)}`), width);
}

/**
 * Rendert die Fleet-Status-Dock-Zeilen aus einer bereits gebauten
 * FleetAgentEntry-Liste. Enthaelt keine Aufrufe von buildFleetEntries()
 * selbst - der Aufrufer (fleet-dock-controller.ts) ist fuer Beschaffung,
 * Throttling und Key-basierte Selektion zustaendig.
 */
export function renderFleetDock(entries: FleetAgentEntry[], selectedKey: string | undefined, opts: RenderFleetDockOptions): string[] {
	const { width, theme, expandedKey, maxRows = MAX_DOCK_ROWS, now = Date.now(), stopArmedKey, active = false } = opts;
	if (entries.length === 0) {
		return [truncLine(theme.fg("dim", "keine aktiven Subagenten"), width)];
	}
	const sorted = sortFleetEntries(entries);
	const visible = sorted.slice(0, maxRows);
	const hidden = sorted.slice(maxRows);
	const lines: string[] = [dockHeaderLine(sorted, theme, width, active)];
	for (const entry of visible) {
		lines.push(entryLine(entry, entry.key === selectedKey, now, theme, width));
		if (expandedKey === entry.key) lines.push(...detailLines(entry, theme, width));
		if (stopArmedKey === entry.key) lines.push(stopConfirmLine(entry, theme, width));
	}
	if (hidden.length > 0) {
		lines.push(truncLine(theme.fg("dim", `  +${hidden.length} weitere`), width));
	}
	if (active) {
		lines.push(dockHintLine(sorted.find((entry) => entry.key === selectedKey), theme, width));
	}
	return lines;
}

/**
 * Fleet Inspector Controller (PHASE-05).
 *
 * Haelt den Interaktionszustand des Inspectors: welcher Dock-Key geoeffnet
 * ist, Scroll-Position (scrollFromBottom, im Renderer geklemmt - siehe
 * fleet-inspector.ts), ob Tool-Details global aufgeklappt sind, und einen
 * throttled Transcript-Read-Cache. Liest Entries NIE ueber eine eigene
 * buildFleetEntries()-Instanz - der injizierte getEntries()-Accessor zeigt
 * in der Wiring-Schicht auf denselben FleetDockController, um einen
 * zweiten, unabhaengig throttled Disk-Scan zu vermeiden.
 *
 * Throttle fuer Transcript-Reads: 500ms (teurer als das bereits im Speicher
 * liegende FleetAgentEntry[], daher groesseres Intervall als der Docks
 * 250ms). invalidateTranscriptCache() wird von der Wiring-Schicht bei jedem
 * tool_result-Event aufgerufen - das ist die "ereignisnahe" Haelfte der
 * Aktualisierung, die 500ms-Throttle der "begrenzte Poll-Fallback" aus
 * CONCEPT.md.
 *
 * Kein Editor-Leerheits-Guard noetig (anders als FleetDockController): der
 * Inspector oeffnet nur aus einem bereits aktiven Dock heraus (per Enter,
 * siehe fleet-dock-controller.ts's onOpenInspector-Option) und die Wiring-
 * Schicht routet waehrend seiner Offenzeit alle Eingaben exklusiv hierher -
 * es gibt keinen Editor-Text-Zustand, gegen den er sich selbstheilen muesste.
 */

import type { ExtensionContext } from "@earendil-works/pi-coding-agent";
import { isKeyRelease, matchesKey, type Component } from "@earendil-works/pi-tui";
import type { FleetAgentEntry } from "../shared/fleet-projection.ts";
import { readChildTranscript, type ReadChildTranscriptResult } from "../shared/fleet-transcript-reader.ts";
import { DEFAULT_INSPECTOR_MAX_VISIBLE_LINES, renderFleetInspector } from "../../tui/fleet-inspector.ts";

type Theme = ExtensionContext["ui"]["theme"];
type TerminalInputResult = { consume?: boolean; data?: string } | undefined;

export const DEFAULT_INSPECTOR_REFRESH_INTERVAL_MS = 500;

const EMPTY_TRANSCRIPT: ReadChildTranscriptResult = { events: [], truncated: false };

export interface FleetInspectorControllerOptions {
	now?: () => number;
	refreshIntervalMs?: number;
	maxVisibleLines?: number;
	trustedRoots?: () => string[];
	readTranscript?: typeof readChildTranscript;
	// PHASE-06: wird nach der zweiten "s"-Bestaetigung mit dem Key des offenen
	// Eintrags aufgerufen - spiegelt FleetDockControllerOptions.onStop, damit
	// Stop von Dock UND Inspector aus identisch funktioniert (siehe DECISIONS.md).
	onStop?: (key: string) => void;
}

export class FleetInspectorController {
	private isOpenFlag = false;
	private openKey: string | undefined;
	private scrollFromBottom = 0;
	private toolDetailsExpanded = false;
	private cachedTranscript: ReadChildTranscriptResult = EMPTY_TRANSCRIPT;
	private cachedAt = Number.NEGATIVE_INFINITY;
	private stopArmed = false;
	private readonly getEntries: () => FleetAgentEntry[];
	private readonly options: FleetInspectorControllerOptions;

	// Keine TS-Parameter-Properties: --experimental-strip-types (test:unit) kann
	// diese Syntax nicht strippen, nur --experimental-transform-types (test:
	// integration/e2e) kann das - siehe FleetDockController fuer denselben Grund.
	constructor(getEntries: () => FleetAgentEntry[], options: FleetInspectorControllerOptions = {}) {
		this.getEntries = getEntries;
		this.options = options;
	}

	private now(): number {
		return this.options.now?.() ?? Date.now();
	}

	private refreshIntervalMs(): number {
		return this.options.refreshIntervalMs ?? DEFAULT_INSPECTOR_REFRESH_INTERVAL_MS;
	}

	private maxVisibleLines(): number {
		return this.options.maxVisibleLines ?? DEFAULT_INSPECTOR_MAX_VISIBLE_LINES;
	}

	private readTranscriptFn(): typeof readChildTranscript {
		return this.options.readTranscript ?? readChildTranscript;
	}

	isOpen(): boolean {
		return this.isOpenFlag;
	}

	/** Oeffnet den Inspector fuer einen Dock-Key; setzt Scroll/Expand/Cache zurueck. */
	open(key: string): void {
		this.isOpenFlag = true;
		this.openKey = key;
		this.scrollFromBottom = 0;
		this.toolDetailsExpanded = false;
		this.stopArmed = false;
		this.invalidateTranscriptCache();
	}

	close(): void {
		this.isOpenFlag = false;
		this.stopArmed = false;
	}

	isStopArmed(): boolean {
		return this.stopArmed;
	}

	getSelectedEntry(): FleetAgentEntry | undefined {
		if (this.openKey === undefined) return undefined;
		return this.getEntries().find((entry) => entry.key === this.openKey);
	}

	getChildren(): FleetAgentEntry[] {
		if (this.openKey === undefined) return [];
		return this.getEntries().filter((entry) => entry.parentKey === this.openKey);
	}

	/** Throttled Transcript-Read; liefert leeres Ergebnis, solange kein Eintrag/transcriptPath vorhanden ist. */
	getTranscript(): ReadChildTranscriptResult {
		const entry = this.getSelectedEntry();
		if (!entry?.transcriptPath) return EMPTY_TRANSCRIPT;
		const now = this.now();
		if (now - this.cachedAt < this.refreshIntervalMs()) return this.cachedTranscript;
		const trustedRoots = this.options.trustedRoots?.() ?? [];
		this.cachedTranscript = this.readTranscriptFn()(entry.transcriptPath, trustedRoots);
		this.cachedAt = now;
		return this.cachedTranscript;
	}

	/** Erzwingt einen sofortigen Re-Read beim naechsten getTranscript()-Aufruf. */
	invalidateTranscriptCache(): void {
		this.cachedAt = Number.NEGATIVE_INFINITY;
	}

	scrollUp(lines = 1): void {
		this.scrollFromBottom = Math.max(0, this.scrollFromBottom + lines);
	}

	scrollDown(lines = 1): void {
		this.scrollFromBottom = Math.max(0, this.scrollFromBottom - lines);
	}

	pageUp(): void {
		this.scrollUp(this.maxVisibleLines());
	}

	pageDown(): void {
		this.scrollDown(this.maxVisibleLines());
	}

	/** Grosszuegig; renderFleetInspector() klemmt auf den tatsaechlichen Zeileninhalt. */
	scrollToTop(): void {
		this.scrollFromBottom = Number.MAX_SAFE_INTEGER;
	}

	scrollToBottom(): void {
		this.scrollFromBottom = 0;
	}

	getScrollFromBottom(): number {
		return this.scrollFromBottom;
	}

	toggleToolDetails(): void {
		this.toolDetailsExpanded = !this.toolDetailsExpanded;
	}

	isToolDetailsExpanded(): boolean {
		return this.toolDetailsExpanded;
	}

	/**
	 * Nur relevant, waehrend isOpen() - das Gating (Inspector vor Dock) erfolgt
	 * in der Wiring-Schicht (fleet-dock-wiring.ts's routeTerminalInput), nicht
	 * hier. Konsumiert alles Bekannte, damit waehrend offenem Inspector nichts
	 * zum Dock oder Editor durchsickert.
	 */
	handleTerminalInput(data: string): TerminalInputResult {
		if (isKeyRelease(data)) return undefined;
		if (!this.isOpenFlag) return undefined;

		if (matchesKey(data, "s")) {
			if (this.stopArmed) {
				this.stopArmed = false;
				if (this.openKey !== undefined) this.options.onStop?.(this.openKey);
				return { consume: true };
			}
			const entry = this.getSelectedEntry();
			if (!entry || entry.source !== "async" || !entry.canStop || !entry.asyncDir) return { consume: true };
			this.stopArmed = true;
			return { consume: true };
		}
		if (this.stopArmed) {
			// Jede andere Taste entwaffnet still statt zusaetzlich ihre eigentliche
			// Wirkung zu entfalten UND das Stoppen auszuloesen - dieselbe Begruendung
			// wie in FleetDockController.handleTerminalInput(). Escape entwaffnet nur
			// (schliesst den Inspector in diesem Tastendruck noch nicht), damit ein
			// versehentliches Doppel-Escape nicht sowohl die Bestaetigung abbricht als
			// auch gleich den Inspector schliesst.
			this.stopArmed = false;
			if (matchesKey(data, "escape")) return { consume: true };
		}

		if (matchesKey(data, "escape")) {
			this.close();
			return { consume: true };
		}
		if (matchesKey(data, "up")) {
			this.scrollUp();
			return { consume: true };
		}
		if (matchesKey(data, "down")) {
			this.scrollDown();
			return { consume: true };
		}
		if (matchesKey(data, "pageUp")) {
			this.pageUp();
			return { consume: true };
		}
		if (matchesKey(data, "pageDown")) {
			this.pageDown();
			return { consume: true };
		}
		if (matchesKey(data, "home")) {
			this.scrollToTop();
			return { consume: true };
		}
		if (matchesKey(data, "end")) {
			this.scrollToBottom();
			return { consume: true };
		}
		if (matchesKey(data, "space")) {
			this.toggleToolDetails();
			return { consume: true };
		}
		if (matchesKey(data, "return")) {
			// Reserviert (Drill-down in Kinder ist Nicht-Ziel dieser Phase) - trotzdem
			// konsumiert, damit nichts zum Editor durchsickert, waehrend offen.
			return { consume: true };
		}
		return undefined;
	}

	/** Component fuer setWidget's Factory-Overload. render() liefert [] wenn geschlossen - erzeugt keine sichtbare Luecke (siehe DECISIONS.md). */
	createComponent(theme: Theme): Component {
		return {
			render: (width: number): string[] => {
				if (!this.isOpenFlag) return [];
				const entry = this.getSelectedEntry();
				const children = this.getChildren();
				const transcript = this.getTranscript();
				return renderFleetInspector(entry, children, transcript, {
					width,
					theme,
					scrollFromBottom: this.scrollFromBottom,
					toolDetailsExpanded: this.toolDetailsExpanded,
					maxVisibleLines: this.maxVisibleLines(),
					now: this.now(),
					stopArmed: this.stopArmed,
				});
			},
			invalidate: () => {},
		};
	}
}

export function createFleetInspectorController(getEntries: () => FleetAgentEntry[], options?: FleetInspectorControllerOptions): FleetInspectorController {
	return new FleetInspectorController(getEntries, options);
}

/**
 * Fleet Inspector – Rendering (PHASE-05).
 *
 * Reine Renderfunktion, analog zu renderFleetDock() (fleet-dock.ts): nimmt
 * einen bereits aufgeloesten FleetAgentEntry, seine Kinder und ein bereits
 * gelesenes Transcript entgegen, kein I/O, kein eigener Zustand (Scroll-
 * Position/Expand-Flag kommen vom Aufrufer). Wiederverwendet stateGlyph()/
 * entryLine() aus fleet-dock.ts fuer die Children-Zeilen, damit sie optisch
 * identisch zu Dock-Zeilen sind.
 */

import type { ExtensionContext } from "@earendil-works/pi-coding-agent";
import { formatDuration, formatTokens } from "../shared/formatters.ts";
import type { FleetAgentEntry, FleetAttentionReason } from "../runs/shared/fleet-projection.ts";
import type { TranscriptEvent } from "../runs/shared/fleet-transcript-reader.ts";
import { compactActivityDetail, entryLine, stateGlyph } from "./fleet-dock.ts";
import { modelThinkingBadge, statJoin, themeBold, truncLine } from "./render.ts";

type Theme = ExtensionContext["ui"]["theme"];

export const DEFAULT_INSPECTOR_MAX_VISIBLE_LINES = 20;
export const MAX_INSPECTOR_CHILDREN_ROWS = 5;

export interface InspectorTranscriptView {
	events: TranscriptEvent[];
	truncated: boolean;
	error?: string;
}

export interface RenderFleetInspectorOptions {
	width: number;
	theme: Theme;
	scrollFromBottom: number;
	toolDetailsExpanded: boolean;
	maxVisibleLines?: number;
	now?: number;
	// PHASE-06: true, waehrend fuer den offenen Eintrag eine Stop-Bestaetigung
	// aussteht (erstes "s" wurde gedrueckt, siehe fleet-inspector-controller.ts).
	stopArmed?: boolean;
}

const ATTENTION_REASON_TEXT: Record<FleetAttentionReason, string> = {
	control_notice: "control notice",
	watchdog_reviewing: "watchdog reviewing",
	watchdog_stalled: "watchdog stalled",
	supervisor_pending: "waiting for supervisor decision",
};

function toolStatusGlyph(event: TranscriptEvent & { type: "tool" }, theme: Theme): string {
	if (event.toolState === "running") return "\u2026";
	if (event.toolState === "awaiting_result") return "(laeuft)";
	return event.isError ? theme.fg("error", "\u2717") : theme.fg("success", "\u2713");
}

function eventLines(event: TranscriptEvent, theme: Theme, width: number, toolDetailsExpanded: boolean): string[] {
	if (event.type === "user") {
		return [truncLine(`${theme.fg("dim", "user:")} ${event.text}`, width)];
	}

	if (event.type === "assistant") {
		const errorSuffix = event.errorMessage ? theme.fg("error", ` (${event.errorMessage})`) : "";
		return [truncLine(`${theme.fg("dim", "assistant:")} ${event.text}${errorSuffix}`, width)];
	}

	if (event.type === "tool") {
		const duration = event.startTs !== undefined && event.endTs !== undefined ? ` ${formatDuration(Math.max(0, event.endTs - event.startTs))}` : "";
		const argsSuffix = event.argsPreview ? ` (${event.argsPreview})` : "";
		const compact = truncLine(`${theme.fg("dim", "tool:")} ${event.toolName}${argsSuffix} ${toolStatusGlyph(event, theme)}${duration}`, width);
		if (!toolDetailsExpanded) return [compact];
		const resultLine = truncLine(theme.fg("dim", `      \u23bf ${event.resultText ?? "(kein Ergebnis)"}`), width);
		return [compact, resultLine];
	}

	// notice
	const color = event.kind === "stderr" ? "warning" : "dim";
	return [truncLine(theme.fg(color, event.text), width)];
}

/**
 * Rendert die Inspector-Zeilen fuer einen ausgewaehlten Agenten. entry
 * undefined bedeutet: der zuvor geoeffnete Lauf ist inzwischen aus der
 * Fleet-Liste verschwunden (abgeschlossen und aus der Retention gefallen).
 * Die live needsAttention/attentionReason von entry fliesst NUR hier ein
 * (eigene Kopfzeile) - sie ist kein TranscriptEvent, da sie ein aktueller
 * Zustand und kein historisches Transcript-Faktum ist.
 */
export function renderFleetInspector(
	entry: FleetAgentEntry | undefined,
	children: FleetAgentEntry[],
	transcript: InspectorTranscriptView,
	opts: RenderFleetInspectorOptions,
): string[] {
	const { width, theme, toolDetailsExpanded } = opts;
	const now = opts.now ?? Date.now();
	const maxVisibleLines = opts.maxVisibleLines ?? DEFAULT_INSPECTOR_MAX_VISIBLE_LINES;

	if (!entry) {
		return [truncLine(theme.fg("dim", "Agent nicht mehr verfuegbar."), width)];
	}

	const lines: string[] = [];

	const location = `${entry.source} \u00b7 run ${entry.runId}${entry.childIndex !== undefined ? ` \u00b7 child ${entry.childIndex}` : ""}`;
	lines.push(truncLine(`${stateGlyph(entry.state, theme)} ${themeBold(theme, entry.agent)}  (${location})`, width));

	const badge = modelThinkingBadge(theme, entry.model, entry.thinking);
	if (badge) lines.push(truncLine(badge.trimStart(), width));

	if (entry.description) lines.push(truncLine(theme.fg("dim", entry.description), width));

	const tokenTotal = entry.tokens ?? entry.tokenUsage?.total;
	const statsLine = statJoin(theme, [
		entry.state,
		formatDuration(Math.max(0, now - entry.startedAt)),
		entry.turnCount !== undefined ? `${entry.turnCount} turns` : "",
		entry.toolCount !== undefined ? `${entry.toolCount} tools` : "",
		tokenTotal !== undefined ? `${formatTokens(tokenTotal)} tok` : "",
		// PHASE-08: gleiche Pfadkuerzung wie im Dock, damit Dock- und
		// Inspector-Statuszeile identisch aussehen.
		entry.activityDetail !== undefined ? compactActivityDetail(entry.activityDetail) : "",
	]);
	if (statsLine) lines.push(truncLine(statsLine, width));

	if (entry.needsAttention || entry.state === "error") {
		const reasonText = (entry.attentionReason ? ATTENTION_REASON_TEXT[entry.attentionReason] : undefined) ?? (entry.state === "error" ? "error" : "needs attention");
		const color = entry.state === "error" ? "error" : "warning";
		lines.push(truncLine(theme.fg(color, `\u26a0 ${reasonText}`), width));
	}

	if (opts.stopArmed) {
		lines.push(truncLine(theme.fg("warning", "Stop bestaetigen: erneut 's' druecken (Escape zum Abbrechen)"), width));
	}

	if (children.length > 0) {
		const visibleChildren = children.slice(0, MAX_INSPECTOR_CHILDREN_ROWS);
		const hiddenChildren = children.slice(MAX_INSPECTOR_CHILDREN_ROWS);
		lines.push(truncLine(theme.fg("dim", "children:"), width));
		for (const child of visibleChildren) lines.push(entryLine(child, false, now, theme, width));
		if (hiddenChildren.length > 0) lines.push(truncLine(theme.fg("dim", `  +${hiddenChildren.length} weitere`), width));
	}

	const truncatedSuffix = transcript.truncated ? " (gekuerzt)" : "";
	lines.push(truncLine(themeBold(theme, `Live-Transcript${truncatedSuffix}:`), width));

	if (transcript.error) {
		lines.push(truncLine(theme.fg("error", transcript.error), width));
	} else {
		const allLines = transcript.events.flatMap((event) => eventLines(event, theme, width, toolDetailsExpanded));
		if (allLines.length === 0) {
			lines.push(truncLine(theme.fg("dim", "keine Ereignisse"), width));
		} else {
			const effectiveScroll = Math.min(Math.max(0, opts.scrollFromBottom), Math.max(0, allLines.length - maxVisibleLines));
			const windowStart = Math.max(0, allLines.length - maxVisibleLines - effectiveScroll);
			const windowEnd = Math.min(allLines.length, windowStart + maxVisibleLines);
			lines.push(...allLines.slice(windowStart, windowEnd));
			if (allLines.length > maxVisibleLines) {
				lines.push(truncLine(theme.fg("dim", `[${windowStart + 1}\u2013${windowEnd} / ${allLines.length}]`), width));
			}
		}
	}

	const stopHint = entry.source === "async" && entry.canStop ? " \u00b7 s stop" : "";
	lines.push(
		truncLine(
			theme.fg(
				"dim",
				`\u2191\u2193 scroll \u00b7 PgUp/PgDn page \u00b7 Space ${toolDetailsExpanded ? "collapse" : "expand"} tool details${stopHint} \u00b7 Esc close`,
			),
			width,
		),
	);

	return lines;
}

/**
 * Sicherer Leser fuer Kind-Transcript-Artefakte (PHASE-05).
 *
 * Liest die von src/shared/child-transcript.ts geschriebenen
 * "_transcript.jsonl"-Dateien (recordType: message/tool_start/tool_end/
 * stdout/stderr/truncated) und uebersetzt sie in ein UI-unabhaengiges
 * TranscriptEvent[]-Modell (user/assistant/tool/notice). Diese Datei ist
 * bewusst framework-unabhaengig (kein pi-tui/pi-coding-agent-Import),
 * analog zu fleet-projection.ts.
 *
 * Sicherheitsalgorithmus spiegelt das bewaehrte, aber private Muster aus
 * src/runs/background/fleet-view.ts (readContainedTextTail) 1:1 - diese
 * Datei bleibt unangetastete Baseline dieser Phase, daher wird pathWithin/
 * isNotFoundError/getErrorMessage hier lokal dupliziert statt importiert:
 * resolve+Praefix-Check -> lstat (ENOENT still leer, Symlink/Non-File
 * ablehnen) -> realpath von Kandidat UND allen Roots, erneuter Containment-
 * Check (schlaegt einen symlinkten Ancestor).
 *
 * Korrelationsalgorithmus (dreistufig, siehe DECISIONS.md): tool_start und
 * tool_end tragen NIE ein Ergebnis - das eigentliche Tool-Ergebnis kommt als
 * eigener recordType:"message"-Eintrag mit role:"toolResult". Zwei FIFO-
 * Queues (openTools/awaitingResult) korrelieren die drei Records; Tiefe 1
 * im Normalfall (ein Kind-Agent fuehrt nie zwei Tools gleichzeitig aus,
 * verifiziert gegen execution.ts/subagent-runner.ts), die Queue-Struktur
 * ist reine Verteidigungstiefe. Fensterrand-Faelle (Start/Ende/Ergebnis vom
 * Tail-Read abgeschnitten) werden nie stillschweigend verworfen, sondern
 * synthetisieren ein bestmoegliches Event.
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { getArtifactsDir } from "../../shared/artifacts.ts";
import { TEMP_ARTIFACTS_DIR } from "../../shared/types.ts";

export const INSPECTOR_TRANSCRIPT_TAIL_BYTES = 512 * 1024;
export const INSPECTOR_MAX_TRANSCRIPT_EVENTS = 300;
export const INSPECTOR_MAX_EVENT_TEXT_CHARS = 4000;

export type TranscriptEvent =
	| { type: "user"; ts: number; text: string; truncated?: boolean }
	| {
			type: "assistant";
			ts: number;
			text: string;
			truncated?: boolean;
			model?: string;
			stopReason?: string;
			errorMessage?: string;
			usage?: { input: number; output: number; total: number };
	  }
	| {
			type: "tool";
			ts: number;
			toolName: string;
			argsPreview?: string;
			startTs?: number;
			endTs?: number;
			resultText?: string;
			resultTruncated?: boolean;
			isError?: boolean;
			toolState: "running" | "awaiting_result" | "complete";
	  }
	| {
			type: "notice";
			ts: number;
			text: string;
			kind: "writer_truncated" | "reader_truncated" | "stdout" | "stderr" | "malformed_lines";
	  };

export interface ParsedChildTranscript {
	events: TranscriptEvent[];
	truncated: boolean;
}

export interface ReadChildTranscriptResult {
	events: TranscriptEvent[];
	truncated: boolean;
	error?: string;
}

export interface InspectorTrustedRootsInput {
	sessionFile?: string | null;
	projectCwd?: string;
	worktreeBaseDir?: string;
}

function pathWithin(base: string, candidate: string): boolean {
	const resolvedBase = path.resolve(base);
	const resolvedCandidate = path.resolve(candidate);
	return resolvedCandidate === resolvedBase || resolvedCandidate.startsWith(`${resolvedBase}${path.sep}`);
}

function getErrorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

function isNotFoundError(error: unknown): boolean {
	return typeof error === "object" && error !== null && "code" in error && (error as NodeJS.ErrnoException).code === "ENOENT";
}

function expandHomeTilde(value: string): string {
	if (value === "~") return os.homedir();
	if (value.startsWith("~/") || value.startsWith(`~${path.sep}`)) return path.join(os.homedir(), value.slice(2));
	return value;
}

/**
 * Trusted Roots fuer readChildTranscript(): dieselbe Ableitung, die der
 * Schreiber (child-transcript.ts ueber shared/artifacts.ts) fuer den
 * aktuellen Kontext verwendet, UNION TEMP_ARTIFACTS_DIR (Fallback/Legacy-
 * Laeufe) UND optional config.worktreeBaseDir (Worktree-Kind-Laeufe rufen
 * getArtifactsDir() mit einem abweichenden effectiveCwd auf, siehe
 * DECISIONS.md). transcriptPath wird NIE ungeprueft vertraut - immer
 * resolve+realpath+Containment-Check gegen dieses Set.
 */
export function resolveInspectorTrustedRoots(input: InspectorTrustedRootsInput): string[] {
	const roots = new Set<string>();
	roots.add(path.resolve(getArtifactsDir(input.sessionFile ?? null, input.projectCwd)));
	if (input.sessionFile) roots.add(path.resolve(getArtifactsDir(input.sessionFile, undefined)));
	roots.add(path.resolve(TEMP_ARTIFACTS_DIR));
	if (input.worktreeBaseDir) roots.add(path.resolve(expandHomeTilde(input.worktreeBaseDir)));
	return [...roots];
}

function capText(text: string): { text: string; truncated: boolean } {
	if (text.length <= INSPECTOR_MAX_EVENT_TEXT_CHARS) return { text, truncated: false };
	return { text: `${text.slice(0, INSPECTOR_MAX_EVENT_TEXT_CHARS)}\u2026`, truncated: true };
}

function normalizeUsageForEvent(value: unknown): { input: number; output: number; total: number } | undefined {
	if (!value || typeof value !== "object") return undefined;
	const raw = value as Record<string, unknown>;
	const input = typeof raw.input === "number" ? raw.input : 0;
	const output = typeof raw.output === "number" ? raw.output : 0;
	return { input, output, total: input + output };
}

interface ToolDraft {
	toolName: string;
	argsPreview?: string;
	startTs: number;
	endTs?: number;
}

/**
 * Reine Funktion (kein fs) - parst bereits extrahierte, vollstaendige
 * JSONL-Zeilen (Fensterrand-/Teilzeilen muss der Aufrufer vorher entfernt
 * haben, siehe readTranscriptLinesTail) in ein sortiertes TranscriptEvent[].
 */
export function parseChildTranscriptLines(lines: string[]): ParsedChildTranscript {
	const events: TranscriptEvent[] = [];
	const openTools: ToolDraft[] = [];
	const awaitingResult: ToolDraft[] = [];
	let writerTruncated = false;
	let malformedLineCount = 0;

	for (const line of lines) {
		if (!line.trim()) continue;
		let record: Record<string, unknown>;
		try {
			record = JSON.parse(line) as Record<string, unknown>;
		} catch {
			malformedLineCount += 1;
			continue;
		}

		const recordType = record.recordType as string | undefined;
		const ts = typeof record.ts === "number" ? record.ts : Date.now();

		if (recordType === "tool_start") {
			const toolName = typeof record.toolName === "string" ? record.toolName : "tool";
			const argsPreview = typeof record.argsPreview === "string" ? record.argsPreview : undefined;
			openTools.push({ toolName, argsPreview, startTs: ts });
			continue;
		}

		if (recordType === "tool_end") {
			const draft = openTools.shift();
			if (draft) {
				draft.endTs = ts;
				awaitingResult.push(draft);
			} else {
				// Fensterrand: der Start wurde vom Tail-Read abgeschnitten. Trotzdem
				// aufnehmen, damit ein nachfolgendes Ergebnis nicht verloren geht.
				const toolName = typeof record.toolName === "string" ? record.toolName : "tool";
				awaitingResult.push({ toolName, startTs: ts, endTs: ts });
			}
			continue;
		}

		if (recordType === "message") {
			const role = record.role as string | undefined;

			if (role === "toolResult") {
				const message = (record.message ?? {}) as Record<string, unknown>;
				const draft = awaitingResult.shift();
				const toolName = draft?.toolName ?? (typeof message.toolName === "string" ? message.toolName : "tool");
				const { text: resultText, truncated: resultTruncated } = capText(typeof record.text === "string" ? record.text : "");
				events.push({
					type: "tool",
					ts: draft?.startTs ?? ts,
					toolName,
					argsPreview: draft?.argsPreview,
					startTs: draft?.startTs,
					endTs: draft?.endTs,
					resultText,
					resultTruncated,
					isError: message.isError === true,
					toolState: "complete",
				});
				continue;
			}

			if (role === "user") {
				const rawText = typeof record.text === "string" ? record.text : undefined;
				if (rawText) {
					const { text, truncated } = capText(rawText);
					events.push({ type: "user", ts, text, truncated });
				}
				continue;
			}

			if (role === "assistant") {
				const rawText = typeof record.text === "string" ? record.text : undefined;
				const errorMessage = typeof record.errorMessage === "string" ? record.errorMessage : undefined;
				if (rawText || errorMessage) {
					const { text, truncated } = capText(rawText ?? "");
					events.push({
						type: "assistant",
						ts,
						text,
						truncated,
						model: typeof record.model === "string" ? record.model : undefined,
						stopReason: typeof record.stopReason === "string" ? record.stopReason : undefined,
						errorMessage,
						usage: normalizeUsageForEvent(record.usage),
					});
				}
				continue;
			}
			// Unbekannte role: still ignorieren.
			continue;
		}

		if (recordType === "truncated") {
			writerTruncated = true;
			const message = typeof record.message === "string" ? record.message : "Transcript truncated by writer.";
			events.push({ type: "notice", ts, text: message, kind: "writer_truncated" });
			continue;
		}

		if (recordType === "stdout" || recordType === "stderr") {
			const { text } = capText(typeof record.text === "string" ? record.text : "");
			events.push({ type: "notice", ts, text, kind: recordType });
			continue;
		}
		// Unbekannter recordType: still ignorieren, kein Fehler.
	}

	// Verbleibende Drafts nach der letzten Zeile sind die Live-Grundlage fuer
	// "Live-Transcript eines laufenden Agents wird korrekt aktualisiert".
	for (const draft of openTools) {
		events.push({ type: "tool", ts: draft.startTs, toolName: draft.toolName, argsPreview: draft.argsPreview, startTs: draft.startTs, toolState: "running" });
	}
	for (const draft of awaitingResult) {
		events.push({
			type: "tool",
			ts: draft.startTs,
			toolName: draft.toolName,
			argsPreview: draft.argsPreview,
			startTs: draft.startTs,
			endTs: draft.endTs,
			toolState: "awaiting_result",
		});
	}

	if (malformedLineCount > 0) {
		events.push({
			type: "notice",
			ts: Date.now(),
			text: `${malformedLineCount} transcript line(s) could not be parsed and were skipped.`,
			kind: "malformed_lines",
		});
	}

	events.sort((a, b) => a.ts - b.ts);

	let truncated = writerTruncated;
	let finalEvents = events;
	if (events.length > INSPECTOR_MAX_TRANSCRIPT_EVENTS) {
		finalEvents = events.slice(events.length - INSPECTOR_MAX_TRANSCRIPT_EVENTS);
		truncated = true;
	}

	return { events: finalEvents, truncated };
}

interface TranscriptLinesTailResult {
	lines: string[];
	windowTruncated: boolean;
}

/**
 * Tail-liest bis zu INSPECTOR_TRANSCRIPT_TAIL_BYTES vom Dateiende. Anders als
 * das textuelle readTextTail-Vorbild in fleet-view.ts wird der letzte Split-
 * Rest IMMER verworfen (nicht nur wenn er leer ist): fuer JSONL ist ein
 * nicht auf "\n" endender Rest zwingend eine unvollstaendige Zeile (der
 * Schreiber war noch mitten im appendFileSync), niemals sinnvoll anzeigbarer
 * Klartext - die Aenderungsregel verlangt, ihn zu ignorieren statt als
 * Fehler zu werfen.
 */
function readTranscriptLinesTail(filePath: string): TranscriptLinesTailResult {
	const stat = fs.statSync(filePath);
	if (stat.size === 0) return { lines: [], windowTruncated: false };

	const bytesToRead = Math.min(stat.size, INSPECTOR_TRANSCRIPT_TAIL_BYTES);
	const start = stat.size - bytesToRead;
	const buffer = Buffer.alloc(bytesToRead);
	const fd = fs.openSync(filePath, "r");
	let bytesRead: number;
	try {
		bytesRead = fs.readSync(fd, buffer, 0, bytesToRead, start);
	} finally {
		fs.closeSync(fd);
	}

	const content = buffer.subarray(0, bytesRead).toString("utf-8");
	let lines = content.split(/\r?\n/);
	lines = lines.slice(0, -1); // letzter Rest: entweder "" (sauber terminiert) oder Teilzeile - immer verwerfen.
	if (start > 0 && lines.length > 0) lines = lines.slice(1); // erster Rest: durch das Tail-Fenster abgeschnitten.

	return { lines, windowTruncated: start > 0 };
}

/**
 * Sicherer Voll-Ablauf: Trusted-Root-Pruefung -> Tail-Read -> Parser.
 * Reihenfolge spiegelt readContainedTextTail() aus fleet-view.ts 1:1.
 */
export function readChildTranscript(filePath: string, trustedRoots: string[]): ReadChildTranscriptResult {
	if (trustedRoots.length === 0) {
		return { events: [], truncated: false, error: `Refusing to read transcript path without a trusted root: ${filePath}` };
	}

	const resolvedPath = path.resolve(filePath);
	if (!trustedRoots.some((root) => pathWithin(root, resolvedPath))) {
		return { events: [], truncated: false, error: `Refusing to read transcript path outside trusted roots: ${filePath}` };
	}

	let lstat: fs.Stats;
	try {
		lstat = fs.lstatSync(resolvedPath);
	} catch (error) {
		if (isNotFoundError(error)) return { events: [], truncated: false };
		return { events: [], truncated: false, error: getErrorMessage(error) };
	}
	if (lstat.isSymbolicLink()) {
		return { events: [], truncated: false, error: `Refusing to read symlink transcript path: ${filePath}` };
	}
	if (!lstat.isFile()) {
		return { events: [], truncated: false, error: `Refusing to read non-file transcript path: ${filePath}` };
	}

	let realPath: string;
	let realRoots: string[];
	try {
		realPath = fs.realpathSync(resolvedPath);
		realRoots = trustedRoots.filter((root) => fs.existsSync(root)).map((root) => fs.realpathSync(root));
	} catch (error) {
		return { events: [], truncated: false, error: getErrorMessage(error) };
	}
	if (!realRoots.some((root) => pathWithin(root, realPath))) {
		return { events: [], truncated: false, error: `Refusing to read transcript path outside trusted roots: ${filePath}` };
	}

	let tail: TranscriptLinesTailResult;
	try {
		tail = readTranscriptLinesTail(resolvedPath);
	} catch (error) {
		return { events: [], truncated: false, error: getErrorMessage(error) };
	}

	const parsed = parseChildTranscriptLines(tail.lines);
	const events = tail.windowTruncated
		? [
				{
					type: "notice" as const,
					ts: parsed.events[0]?.ts ?? Date.now(),
					text: "Earlier transcript content was omitted (file exceeds the read window).",
					kind: "reader_truncated" as const,
				},
				...parsed.events,
			]
		: parsed.events;

	return { events, truncated: tail.windowTruncated || parsed.truncated };
}

import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import * as fs from "node:fs";
import * as path from "node:path";
import { renderWidget, widgetRenderKey } from "../../tui/render.ts";
import { formatControlNoticeMessage } from "../shared/subagent-control.ts";
import {
	type AsyncJobState,
	type AsyncStartedEvent,
	type ControlEvent,
	type SubagentState,
	POLL_INTERVAL_MS,
	RESULTS_DIR,
	SUBAGENT_CONTROL_EVENT,
	SUBAGENT_CONTROL_INTERCOM_EVENT,
} from "../../shared/types.ts";
import { readStatus } from "../../shared/utils.ts";
import { normalizeParallelGroups } from "./parallel-groups.ts";
import { reconcileAsyncRun, reconcileNestedAsyncDescendants } from "./stale-run-reconciler.ts";
import { hasLiveNestedDescendants, updateAsyncJobNestedProjection } from "../shared/nested-events.ts";
import { listAsyncRuns, type AsyncRunSummary } from "./async-status.ts";

interface AsyncJobTrackerOptions {
	completionRetentionMs?: number;
	pollIntervalMs?: number;
	resultsDir?: string;
	kill?: (pid: number, signal?: NodeJS.Signals | 0) => boolean;
	now?: () => number;
	showAsyncWidget?: boolean;
}

const CONTROL_EVENT_READ_CHUNK_BYTES = 64 * 1024;
const MAX_CONTROL_EVENT_LINE_BYTES = 1024 * 1024;
const CONTROL_EVENT_SCAN_WINDOW_BYTES = 2 * 1024 * 1024;

export function createAsyncJobTracker(pi: Pick<ExtensionAPI, "events">, state: SubagentState, asyncDirRoot: string, options: AsyncJobTrackerOptions = {}): {
	ensurePoller: () => void;
	handleStarted: (data: unknown) => void;
	handleComplete: (data: unknown) => void;
	resetJobs: (ctx?: ExtensionContext) => void;
	restoreActiveJobs: (ctx?: ExtensionContext) => void;
} {
	const completionRetentionMs = options.completionRetentionMs ?? 10000;
	const pollIntervalMs = options.pollIntervalMs ?? POLL_INTERVAL_MS;
	const resultsDir = options.resultsDir ?? RESULTS_DIR;
	const showAsyncWidget = options.showAsyncWidget !== false;
	const rerenderWidget = (ctx: ExtensionContext, jobs = Array.from(state.asyncJobs.values())) => {
		if (state.suppressAsyncWidget) {
			// PHASE-06: FleetView ist aktiv und unterdrueckt das alte Widget - der
			// renderWidget()-Aufruf entfaellt, aber ein Repaint wird trotzdem
			// angestossen, damit Async-Start/-Abschluss/Pause/Stop/Fehler auch dann
			// sofort im Fleet Dock sichtbar werden, wenn die Aenderung nicht ueber
			// einen tool_result-Event laeuft (z.B. ein reiner Poller-Tick). Ohne
			// diesen Aufruf aktualisiert sich das throttled FleetDockController-
			// Widget erst beim naechsten ohnehin stattfindenden Repaint (z.B.
			// Tastendruck) - siehe DECISIONS.md.
			ctx.ui.requestRender?.();
			return;
		}
		if (!showAsyncWidget) return;
		renderWidget(ctx, jobs);
		ctx.ui.requestRender?.();
	};
	const restoredControlEventCursor = (asyncDir: string) => {
		try {
			return fs.statSync(path.join(asyncDir, "events.jsonl")).size;
		} catch (error) {
			if ((error as NodeJS.ErrnoException).code === "ENOENT") return 0;
			throw error;
		}
	};
	const summaryToJob = (run: AsyncRunSummary): AsyncJobState => {
		const groups = normalizeParallelGroups(run.parallelGroups, run.steps.length, run.chainStepCount ?? run.steps.length);
		const activeGroup = run.currentStep !== undefined
			? groups.find((group) => run.currentStep! >= group.start && run.currentStep! < group.start + group.count)
			: undefined;
		const visibleSteps = activeGroup
			? run.steps.slice(activeGroup.start, activeGroup.start + activeGroup.count).map((step, index) => ({ ...step, index: activeGroup.start + index }))
			: run.steps.map((step, index) => ({ ...step, index }));
		return {
			asyncId: run.id,
			asyncDir: run.asyncDir,
			status: run.state,
			sessionId: run.sessionId,
			activityState: run.activityState,
			lastActivityAt: run.lastActivityAt,
			currentTool: run.currentTool,
			currentToolStartedAt: run.currentToolStartedAt,
			currentPath: run.currentPath,
			turnCount: run.turnCount,
			toolCount: run.toolCount,
			mode: run.mode,
			agents: visibleSteps.map((step) => step.agent),
			currentStep: run.currentStep,
			chainStepCount: run.chainStepCount,
			parallelGroups: groups,
			steps: visibleSteps,
			stepsTotal: visibleSteps.length,
			runningSteps: visibleSteps.filter((step) => step.status === "running").length,
			completedSteps: visibleSteps.filter((step) => step.status === "complete" || step.status === "completed").length,
			hasParallelGroups: groups.length > 0,
			activeParallelGroup: Boolean(activeGroup),
			startedAt: run.startedAt,
			updatedAt: run.lastUpdate ?? run.startedAt,
			timeoutMs: run.timeoutMs,
			deadlineAt: run.deadlineAt,
			timedOut: run.timedOut,
			stopped: run.stopped,
			turnBudget: run.turnBudget,
			turnBudgetExceeded: run.turnBudgetExceeded,
			wrapUpRequested: run.wrapUpRequested,
			sessionDir: run.sessionDir,
			outputFile: run.outputFile,
			totalTokens: run.totalTokens,
			sessionFile: run.sessionFile,
			controlEventCursor: restoredControlEventCursor(run.asyncDir),
			nestedChildren: run.nestedChildren,
		};
	};
	const cancelCleanup = (asyncId: string) => {
		const existingTimer = state.cleanupTimers.get(asyncId);
		if (!existingTimer) return;
		clearTimeout(existingTimer);
		state.cleanupTimers.delete(asyncId);
	};
	const scheduleCleanup = (asyncId: string) => {
		cancelCleanup(asyncId);
		const timer = setTimeout(() => {
			state.cleanupTimers.delete(asyncId);
			state.asyncJobs.delete(asyncId);
			if (state.lastUiContext) {
				rerenderWidget(state.lastUiContext);
			}
		}, completionRetentionMs);
		state.cleanupTimers.set(asyncId, timer);
	};
	const emitNewControlEvents = (job: AsyncJobState) => {
		const eventsPath = path.join(job.asyncDir, "events.jsonl");
		let fd: number;
		try {
			fd = fs.openSync(eventsPath, "r");
		} catch (error) {
			if ((error as NodeJS.ErrnoException).code === "ENOENT") return;
			console.error(`Failed to open async control events for '${job.asyncDir}':`, error);
			return;
		}
		try {
			const stat = fs.fstatSync(fd);
			const savedCursor = job.controlEventCursor;
			let cursor = stat.size < (savedCursor ?? 0) ? 0 : (savedCursor ?? 0);
			const startedFromTail = savedCursor === undefined && stat.size > CONTROL_EVENT_SCAN_WINDOW_BYTES;
			if (startedFromTail) cursor = stat.size - CONTROL_EVENT_SCAN_WINDOW_BYTES;
			if (stat.size <= cursor) return;
			const scanEnd = Math.min(stat.size, cursor + CONTROL_EVENT_SCAN_WINDOW_BYTES);
			const handleLine = (line: string) => {
				if (!line.trim()) return;
				let parsed: unknown;
				try {
					parsed = JSON.parse(line);
				} catch (error) {
					console.error(`Ignoring malformed async control event in '${eventsPath}':`, error);
					return;
				}
				if (!parsed || typeof parsed !== "object" || (parsed as { type?: unknown }).type !== "subagent.control") return;
				const record = parsed as { event?: ControlEvent; channels?: string[]; childIntercomTarget?: string; noticeText?: string; intercom?: { to?: string; message?: string } };
				if (!record.event || !Array.isArray(record.channels)) return;
				const payload = {
					event: record.event,
					source: "async" as const,
					asyncDir: job.asyncDir,
					childIntercomTarget: record.childIntercomTarget,
					noticeText: record.noticeText ?? formatControlNoticeMessage(record.event, record.childIntercomTarget),
				};
				if (record.channels.includes("event")) {
					pi.events.emit(SUBAGENT_CONTROL_EVENT, payload);
				}
				if (record.event.type !== "active_long_running" && record.channels.includes("intercom") && record.intercom?.to && record.intercom.message) {
					pi.events.emit(SUBAGENT_CONTROL_INTERCOM_EVENT, {
						...payload,
						to: record.intercom.to,
						message: record.intercom.message,
					});
				}
			};
			let readCursor = cursor;
			let lastCompleteCursor = cursor;
			let lineParts: Buffer[] = [];
			let lineBytes = 0;
			let skippingOversizedLine = startedFromTail;
			const appendLineSegment = (segment: Buffer) => {
				if (segment.length === 0 || skippingOversizedLine) return;
				if (lineBytes + segment.length > MAX_CONTROL_EVENT_LINE_BYTES) {
					lineParts = [];
					lineBytes = 0;
					skippingOversizedLine = true;
					return;
				}
				lineParts.push(segment);
				lineBytes += segment.length;
			};
			while (readCursor < scanEnd) {
				const toRead = Math.min(CONTROL_EVENT_READ_CHUNK_BYTES, scanEnd - readCursor);
				const buffer = Buffer.alloc(toRead);
				const bytesRead = fs.readSync(fd, buffer, 0, toRead, readCursor);
				if (bytesRead <= 0) break;
				const chunk = bytesRead === buffer.length ? buffer : buffer.subarray(0, bytesRead);
				let lineStart = 0;
				for (let index = 0; index < chunk.length; index++) {
					if (chunk[index] !== 0x0a) continue;
					appendLineSegment(chunk.subarray(lineStart, index));
					if (!skippingOversizedLine && lineBytes > 0) {
						handleLine(Buffer.concat(lineParts, lineBytes).toString("utf-8"));
					}
					lineParts = [];
					lineBytes = 0;
					skippingOversizedLine = false;
					lastCompleteCursor = readCursor + index + 1;
					lineStart = index + 1;
				}
				appendLineSegment(chunk.subarray(lineStart));
				readCursor += bytesRead;
				if (skippingOversizedLine) job.controlEventCursor = readCursor;
			}
			if (lastCompleteCursor > cursor) job.controlEventCursor = lastCompleteCursor;
			else if (scanEnd < stat.size || startedFromTail) job.controlEventCursor = scanEnd;
		} catch (error) {
			console.error(`Failed to read async control events for '${job.asyncDir}':`, error);
		} finally {
			fs.closeSync(fd);
		}
	};

	const ensurePoller = () => {
		if (state.poller) return;
		state.poller = setInterval(() => {
			if (state.asyncJobs.size === 0) {
				if (state.lastUiContext?.hasUI) rerenderWidget(state.lastUiContext, []);
				if (state.poller) {
					clearInterval(state.poller);
					state.poller = null;
				}
				return;
			}

			let widgetChanged = false;
			for (const job of state.asyncJobs.values()) {
				const widgetStateBefore = widgetRenderKey(job);
				let nestedRefreshFailed = false;
				const refreshNestedProjection = () => {
					try {
						updateAsyncJobNestedProjection(job);
					} catch (error) {
						nestedRefreshFailed = true;
						console.error(`Failed to refresh nested async descendants for '${job.asyncDir}':`, error);
					}
				};
				const reconcileNestedDescendants = () => {
					try {
						if (job.nestedRoute) reconcileNestedAsyncDescendants(job.nestedRoute, { resultsDir, kill: options.kill, now: options.now });
					} catch (error) {
						nestedRefreshFailed = true;
						console.error(`Failed to refresh nested async descendants for '${job.asyncDir}':`, error);
					}
					refreshNestedProjection();
				};
				try {
					emitNewControlEvents(job);
					reconcileNestedDescendants();
					const reconciliation = reconcileAsyncRun(job.asyncDir, {
						resultsDir,
						kill: options.kill,
						now: options.now,
						startedRun: {
							runId: job.asyncId,
							pid: job.pid,
							sessionId: job.sessionId,
							mode: job.mode,
							agents: job.agents,
							chainStepCount: job.chainStepCount,
							parallelGroups: job.parallelGroups,
							startedAt: job.startedAt,
							sessionFile: job.sessionFile,
						},
					});
					const status = reconciliation.status ?? readStatus(job.asyncDir);
					if (status) {
						const previousStatus = job.status;
						job.status = status.state;
						if (job.status !== "complete" && job.status !== "failed" && job.status !== "paused" && job.status !== "stopped") cancelCleanup(job.asyncId);
						job.sessionId = status.sessionId ?? job.sessionId;
						job.activityState = status.activityState;
						job.lastActivityAt = status.lastActivityAt ?? job.lastActivityAt;
						job.currentTool = status.currentTool;
						job.currentToolStartedAt = status.currentToolStartedAt;
						job.currentPath = status.currentPath;
						job.turnCount = status.turnCount ?? job.turnCount;
						job.toolCount = status.toolCount ?? job.toolCount;
						job.mode = status.mode;
						job.currentStep = status.currentStep ?? job.currentStep;
						job.chainStepCount = status.chainStepCount ?? job.chainStepCount;
						job.startedAt = status.startedAt ?? job.startedAt;
						if (status.lastUpdate !== undefined) job.updatedAt = status.lastUpdate;
						if (status.steps?.length) {
							const groups = normalizeParallelGroups(status.parallelGroups, status.steps.length, status.chainStepCount ?? status.steps.length);
							job.parallelGroups = groups.length ? groups : job.parallelGroups;
							job.hasParallelGroups = groups.length > 0 || job.hasParallelGroups;
							const activeGroup = status.currentStep !== undefined
								? groups.find((group) => status.currentStep! >= group.start && status.currentStep! < group.start + group.count)
								: undefined;
							const visibleSteps = activeGroup
								? status.steps.slice(activeGroup.start, activeGroup.start + activeGroup.count).map((step, index) => ({ ...step, index: activeGroup.start + index }))
								: status.steps.map((step, index) => ({ ...step, index }));
							job.activeParallelGroup = Boolean(activeGroup);
							job.agents = visibleSteps.map((step) => step.agent);
							job.steps = visibleSteps;
							refreshNestedProjection();
							job.stepsTotal = visibleSteps.length;
							job.runningSteps = visibleSteps.filter((step) => step.status === "running").length;
							job.completedSteps = visibleSteps.filter((step) => step.status === "complete" || step.status === "completed").length;
							if (status.state === "complete") job.completedSteps = visibleSteps.length;
						}
						job.sessionDir = status.sessionDir ?? job.sessionDir;
						job.outputFile = status.outputFile ?? job.outputFile;
						job.totalTokens = status.totalTokens ?? job.totalTokens;
						job.timeoutMs = status.timeoutMs ?? job.timeoutMs;
						job.deadlineAt = status.deadlineAt ?? job.deadlineAt;
						job.timedOut = status.timedOut ?? job.timedOut;
						job.stopped = status.stopped ?? job.stopped;
						job.turnBudget = status.turnBudget ?? job.turnBudget;
						job.turnBudgetExceeded = status.turnBudgetExceeded ?? job.turnBudgetExceeded;
						job.wrapUpRequested = status.wrapUpRequested ?? job.wrapUpRequested;
						job.sessionFile = status.sessionFile ?? job.sessionFile;
						if ((job.status === "complete" || job.status === "failed" || job.status === "paused" || job.status === "stopped") && !nestedRefreshFailed && !hasLiveNestedDescendants(job.nestedChildren) && (previousStatus !== job.status || !state.cleanupTimers.has(job.asyncId))) {
							scheduleCleanup(job.asyncId);
						}
						if (widgetRenderKey(job) !== widgetStateBefore) widgetChanged = true;
						continue;
					}
					if (job.status === "queued") {
						job.status = "running";
						job.updatedAt = Date.now();
					}
				} catch (error) {
					if (job.status !== "failed") {
						console.error(`Failed to read async status for '${job.asyncDir}':`, error);
						job.status = "failed";
						job.updatedAt = Date.now();
					}
					if (!hasLiveNestedDescendants(job.nestedChildren) && !state.cleanupTimers.has(job.asyncId)) {
						scheduleCleanup(job.asyncId);
					}
				}
				if (widgetRenderKey(job) !== widgetStateBefore) widgetChanged = true;
			}

			if (widgetChanged && state.lastUiContext?.hasUI) rerenderWidget(state.lastUiContext);
		}, pollIntervalMs);
		state.poller.unref?.();
	};

	const handleStarted = (data: unknown) => {
		const info = data as AsyncStartedEvent;
		if (!info.id) return;
		if (typeof state.currentSessionId === "string" && info.sessionId !== state.currentSessionId) return;
		const now = Date.now();
		const asyncDir = info.asyncDir ?? path.join(asyncDirRoot, info.id);
		const rawAgents = info.agents?.length ? info.agents : info.chain && info.chain.length > 0 ? info.chain : info.agent ? [info.agent] : undefined;
		const validParallelGroups = normalizeParallelGroups(info.parallelGroups, Number.MAX_SAFE_INTEGER, info.chainStepCount ?? Number.MAX_SAFE_INTEGER);
		const firstGroup = validParallelGroups.find((group) => group.start === 0);
		const firstGroupCount = firstGroup?.count;
		const agents = firstGroupCount && firstGroupCount > 0
			? rawAgents?.slice(0, firstGroupCount)
			: rawAgents;
		state.asyncJobs.set(info.id, {
			asyncId: info.id,
			asyncDir,
			status: "queued",
			pid: typeof info.pid === "number" ? info.pid : undefined,
			...(typeof info.sessionId === "string" ? { sessionId: info.sessionId } : {}),
			mode: info.mode ?? (info.chain ? "chain" : "single"),
			agents,
			chainStepCount: info.chainStepCount,
			parallelGroups: validParallelGroups,
			nestedRoute: info.nestedRoute,
			stepsTotal: firstGroupCount ?? agents?.length,
			hasParallelGroups: validParallelGroups.length > 0,
			activeParallelGroup: Boolean(firstGroupCount && firstGroupCount > 0),
			startedAt: now,
			updatedAt: now,
			timeoutMs: info.timeoutMs,
			deadlineAt: info.deadlineAt,
			turnBudget: info.turnBudget,
			controlEventCursor: 0,
		});
		ensurePoller();
		if (state.lastUiContext) {
			rerenderWidget(state.lastUiContext);
		}
	};

	const handleComplete = (data: unknown) => {
		const result = data as { id?: string; success?: boolean; state?: AsyncJobState["status"]; asyncDir?: string; sessionId?: string; stopped?: boolean };
		if (typeof state.currentSessionId === "string" && result.sessionId !== state.currentSessionId) return;
		const asyncId = result.id;
		if (!asyncId) return;
		const job = state.asyncJobs.get(asyncId);
		let nestedRefreshFailed = false;
		if (job) {
			job.status = result.state ?? (result.success ? "complete" : "failed");
			job.stopped = result.stopped ?? job.stopped;
			job.updatedAt = Date.now();
			if (result.asyncDir) job.asyncDir = result.asyncDir;
			try {
				updateAsyncJobNestedProjection(job);
			} catch (error) {
				nestedRefreshFailed = true;
				console.error(`Failed to refresh nested async descendants for '${job.asyncDir}':`, error);
			}
		}
		if (state.lastUiContext) {
			rerenderWidget(state.lastUiContext);
		}
		if (!nestedRefreshFailed && !hasLiveNestedDescendants(job?.nestedChildren)) scheduleCleanup(asyncId);
	};

	const resetJobs = (ctx?: ExtensionContext) => {
		for (const timer of state.cleanupTimers.values()) {
			clearTimeout(timer);
		}
		state.cleanupTimers.clear();
		state.asyncJobs.clear();
		state.foregroundControls?.clear();
		state.lastForegroundControlId = null;
		state.resultFileCoalescer.clear();
		if (ctx?.hasUI) {
			state.lastUiContext = ctx;
			rerenderWidget(ctx, []);
		}
	};

	const restoreActiveJobs = (ctx?: ExtensionContext) => {
		if (ctx?.hasUI) state.lastUiContext = ctx;
		if (!state.currentSessionId) return;
		let runs: AsyncRunSummary[];
		try {
			runs = listAsyncRuns(asyncDirRoot, { states: ["queued", "running"], sessionId: state.currentSessionId, resultsDir, kill: options.kill, now: options.now });
		} catch (error) {
			console.error(`Failed to restore active async jobs from '${asyncDirRoot}':`, error);
			return;
		}
		for (const run of runs) {
			state.asyncJobs.set(run.id, summaryToJob(run));
		}
		if (runs.length === 0) return;
		ensurePoller();
		if (state.lastUiContext?.hasUI) rerenderWidget(state.lastUiContext);
	};

	return { ensurePoller, handleStarted, handleComplete, resetJobs, restoreActiveJobs };
}

#!/usr/bin/env node

/**
 * pi-subagents installer
 * 
 * Usage:
 *   npx pi-subagents          # Install to ~/.pi/agent/extensions/subagent
 *   npx pi-subagents --remove # Remove the extension
 */

import { execSync } from "node:child_process";
import * as fs from "node:fs";
import * as path from "node:path";
import * as os from "node:os";

const EXTENSION_DIR = path.join(os.homedir(), ".pi", "agent", "extensions", "subagent");
const REPO_URL = "https://github.com/nicobailon/pi-subagents.git";

const args = process.argv.slice(2);
const isRemove = args.includes("--remove") || args.includes("-r");
const isHelp = args.includes("--help") || args.includes("-h");

if (isHelp) {
	console.log(`
pi-subagents - Pi extension for delegating tasks to subagents

Usage:
  npx pi-subagents          Install the extension
  npx pi-subagents --remove Remove the extension
  npx pi-subagents --help   Show this help

Installation directory: ${EXTENSION_DIR}
`);
	process.exit(0);
}

if (isRemove) {
	if (fs.existsSync(EXTENSION_DIR)) {
		console.log(`Removing ${EXTENSION_DIR}...`);
		fs.rmSync(EXTENSION_DIR, { recursive: true });
		console.log("pi-subagents removed");
	} else {
		console.log("pi-subagents is not installed");
	}
	process.exit(0);
}

// Install
console.log("Installing pi-subagents...\n");

// Ensure parent directory exists
const parentDir = path.dirname(EXTENSION_DIR);
if (!fs.existsSync(parentDir)) {
	fs.mkdirSync(parentDir, { recursive: true });
}

// Check if already installed
if (fs.existsSync(EXTENSION_DIR)) {
	const isGitRepo = fs.existsSync(path.join(EXTENSION_DIR, ".git"));
	if (isGitRepo) {
		console.log("Updating existing installation...");
		try {
			execSync("git pull", { cwd: EXTENSION_DIR, stdio: "inherit" });
			console.log("\npi-subagents updated");
		} catch (err) {
			console.error("Failed to update. Try removing and reinstalling:");
			console.error("  npx pi-subagents --remove && npx pi-subagents");
			process.exit(1);
		}
	} else {
		console.log(`Directory exists but is not a git repo: ${EXTENSION_DIR}`);
		console.log("Remove it first with: npx pi-subagents --remove");
		process.exit(1);
	}
} else {
	// Fresh install
	console.log(`Cloning to ${EXTENSION_DIR}...`);
	try {
		execSync(`git clone ${REPO_URL} "${EXTENSION_DIR}"`, { stdio: "inherit" });
		console.log("\npi-subagents installed");
	} catch (err) {
		console.error("Failed to clone repository");
		process.exit(1);
	}
}

console.log(`
The extension is now available in pi. Tools added:
  • subagent - Delegate tasks to agents and inspect run status
  • wait - Block until background subagent runs finish (delivers their results)

Documentation: ${EXTENSION_DIR}/README.md
`);

import assert from "node:assert/strict";
import * as fs from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";

const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");

const sourceImportPattern = /from\s+["'](@earendil-works\/[^"']+)["']|import\s+["'](@earendil-works\/[^"']+)["']/g;
const oldPiScopePattern = /@mariozechner\/pi-/;
const piPackageJsonSubpathPattern = /@earendil-works\/pi-[^"']+\/package\.json/;
const cjsPiPackageResolutionPattern = /require(?:\.resolve)?\(\s*["']@earendil-works\/pi-/;
const exactVersionPattern = /^\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/;

function collectTsFiles(dir: string): string[] {
	const files: string[] = [];
	for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
		const entryPath = path.join(dir, entry.name);
		if (entry.isDirectory()) {
			collectTsFiles(entryPath).forEach((file) => files.push(file));
		} else if (entry.name.endsWith(".ts")) {
			files.push(entryPath);
		}
	}
	return files;
}

test("direct @earendil-works runtime imports are declared for CI installs", () => {
	const packageJson = JSON.parse(fs.readFileSync(path.join(projectRoot, "package.json"), "utf-8"));
	const declared = new Set([
		...Object.keys(packageJson.dependencies ?? {}),
		...Object.keys(packageJson.devDependencies ?? {}),
	]);
	const imported = new Set<string>();

	for (const file of [...collectTsFiles(path.join(projectRoot, "src")), ...collectTsFiles(path.join(projectRoot, "test"))]) {
		const source = fs.readFileSync(file, "utf-8");
		for (const match of source.matchAll(sourceImportPattern)) {
			imported.add(match[1] ?? match[2]!);
		}
	}

	const missing = [...imported].filter((specifier) => !declared.has(specifier)).sort();
	assert.deepEqual(missing, []);
});

test("direct dependency declarations are exact version pins", () => {
	const packageJson = JSON.parse(fs.readFileSync(path.join(projectRoot, "package.json"), "utf-8"));

	for (const section of ["dependencies", "devDependencies"] as const) {
		for (const [name, version] of Object.entries<string>(packageJson[section] ?? {})) {
			assert.match(version, exactVersionPattern, `${section}.${name} should use an exact version`);
		}
	}
});

test("old pi package scope is not used by source or tests", () => {
	for (const file of [...collectTsFiles(path.join(projectRoot, "src")), ...collectTsFiles(path.join(projectRoot, "test"))]) {
		const source = fs.readFileSync(file, "utf-8");
		assert.equal(oldPiScopePattern.test(source), false, file);
	}
});

test("Pi package resolution stays export-map safe", () => {
	for (const file of [...collectTsFiles(path.join(projectRoot, "src")), ...collectTsFiles(path.join(projectRoot, "test"))]) {
		const source = fs.readFileSync(file, "utf-8");
		assert.equal(piPackageJsonSubpathPattern.test(source), false, `${file} should not resolve unexported package.json subpaths`);
		assert.equal(cjsPiPackageResolutionPattern.test(source), false, `${file} should not use CommonJS resolution for ESM-only Pi packages`);
	}
});

